-- @seq 391
CREATE FUNCTION public.efile_build_1099_filing(p_tenant_id uuid, p_tax_year integer, p_form text DEFAULT '1099-NEC'::text, p_entity_id uuid DEFAULT NULL::uuid, p_allow_partial boolean DEFAULT false, p_environment text DEFAULT 'production'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid := coalesce(p_entity_id, acct_default_entity(p_tenant_id)); v_id uuid; v_issues text[]; v_seq int := 0; r record; v_form uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_form NOT IN ('1099-NEC','1099-MISC') THEN RAISE EXCEPTION 'Unsupported form %', p_form; END IF;
  SELECT coalesce(array_agg(x.vendor_name || ': ' || array_to_string(x.issues, ', ')), '{}') INTO v_issues
    FROM acct_1099_export(p_tenant_id, p_tax_year, p_form, v_entity) x WHERE x.must_file AND NOT x.ready_to_file;
  IF v_issues <> '{}' AND NOT p_allow_partial THEN
    RAISE EXCEPTION 'Cannot build % for %: % payee(s) not ready - %', p_form, p_tax_year, cardinality(v_issues), array_to_string(v_issues, '; ');
  END IF;
  PERFORM acct_generate_1099s(p_tenant_id, p_tax_year);
  INSERT INTO efile_filings(tenant_id, entity_id, form_code, tax_year, period_label, due_date, channel, environment, status, blocking_issues, created_by)
  VALUES (p_tenant_id, v_entity, p_form, p_tax_year, p_tax_year::text, CASE WHEN p_form = '1099-NEC' THEN make_date(p_tax_year + 1, 1, 31) END,
          'iris_a2a', p_environment, 'draft', v_issues, auth.uid())
  RETURNING id INTO v_id;
  FOR r IN SELECT * FROM acct_1099_export(p_tenant_id, p_tax_year, p_form, v_entity) x WHERE x.must_file AND x.ready_to_file ORDER BY x.vendor_name LOOP
    v_seq := v_seq + 1;
    SELECT f.id INTO v_form FROM acct_payroll_tax_forms f
     WHERE f.tenant_id = p_tenant_id AND f.vendor_id = r.vendor_id AND f.form_type = p_form AND f.tax_year = p_tax_year AND f.status <> 'void'
     ORDER BY f.created_at DESC LIMIT 1;
    INSERT INTO efile_filing_records(tenant_id, filing_id, record_seq, source_form_id, vendor_id, payee_name, tin_type, tin_vault_id, tin_last4,
                                     mailing_address, box_values, amount)
    VALUES (p_tenant_id, v_id, v_seq, v_form, r.vendor_id, coalesce(nullif(r.legal_name,''), r.vendor_name), r.tin_type, r.tin_vault_id, r.tin_last4,
            r.mailing_address, jsonb_build_object(r.box, r.amount), r.amount);
  END LOOP;
  IF v_seq = 0 THEN RAISE EXCEPTION 'No % payees ready to file for %', p_form, p_tax_year; END IF;
  UPDATE efile_filings SET record_count = v_seq, total_amount = (SELECT sum(amount) FROM efile_filing_records WHERE filing_id = v_id),
         status = 'ready', updated_at = now() WHERE id = v_id;
  RETURN v_id;
END $$;

-- @seq 392
CREATE FUNCTION public.efile_build_payroll_filing(p_tenant_id uuid, p_form text, p_tax_year integer, p_period_label text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; v_n int; v_code text;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_code := CASE p_form WHEN 'state_withholding' THEN 'STATE-WH' ELSE p_form END;
  IF EXISTS (SELECT 1 FROM efile_form_types WHERE code = v_code AND default_channel = 'mef') THEN
    RAISE EXCEPTION 'Form % is filed through Unsaid MeF: build it with mef_build_941(tenant, year, quarter, deposits) and sign it', v_code;
  END IF;
  IF v_code NOT IN ('W-2','STATE-WH') THEN RAISE EXCEPTION 'Unsupported payroll form %', p_form; END IF;
  INSERT INTO efile_filings(tenant_id, entity_id, form_code, tax_year, period_label, channel, status, created_by)
  VALUES (p_tenant_id, acct_default_entity(p_tenant_id), v_code, p_tax_year, coalesce(p_period_label, p_tax_year::text), 'payroll_provider', 'ready', auth.uid())
  RETURNING id INTO v_id;
  INSERT INTO efile_filing_records(tenant_id, filing_id, record_seq, source_form_id, employee_id, box_values, amount)
  SELECT p_tenant_id, v_id, row_number() OVER (ORDER BY f.created_at), f.id, f.employee_id, f.box_values,
         coalesce(nullif(f.box_values->>'total','')::numeric, 0)
    FROM acct_payroll_tax_forms f
   WHERE f.tenant_id = p_tenant_id AND f.form_type = p_form AND f.tax_year = p_tax_year AND f.status IN ('draft','generated')
     AND (p_period_label IS NULL OR f.period_label = p_period_label);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE EXCEPTION 'No % forms to file for % %', p_form, p_tax_year, coalesce(p_period_label,''); END IF;
  UPDATE efile_filings SET record_count = v_n, total_amount = (SELECT sum(amount) FROM efile_filing_records WHERE filing_id = v_id) WHERE id = v_id;
  RETURN v_id;
END $$;

-- @seq 393
CREATE FUNCTION public.efile_build_sales_tax_filing(p_tax_filing_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_tax_filings%ROWTYPE; j acct_tax_jurisdictions%ROWTYPE; v_ch text; v_id uuid;
BEGIN
  SELECT * INTO f FROM acct_tax_filings WHERE id = p_tax_filing_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown tax filing %', p_tax_filing_id; END IF;
  PERFORM acct_assert_access(f.tenant_id);
  SELECT * INTO j FROM acct_tax_jurisdictions WHERE id = f.jurisdiction_id;
  IF j.state_code IS NULL OR j.level <> 'state' THEN RAISE EXCEPTION 'Sales tax e-file needs a state-level filing (jurisdiction %)', j.code; END IF;
  SELECT channel INTO v_ch FROM efile_state_settings WHERE tenant_id = f.tenant_id AND state_code = j.state_code;
  INSERT INTO efile_filings(tenant_id, entity_id, form_code, state_code, tax_year, period_label, period_start, period_end, due_date,
                            channel, status, tax_filing_id, record_count, total_amount, created_by)
  VALUES (f.tenant_id, coalesce(f.entity_id, acct_default_entity(f.tenant_id)), 'STATE-SALES', j.state_code, extract(year FROM f.period_end)::int,
          f.period_label, f.period_start, f.period_end, f.due_date, coalesce(v_ch, 'state_portal'), 'ready', f.id, 1, f.amount_due, auth.uid())
  RETURNING id INTO v_id;
  INSERT INTO efile_filing_records(tenant_id, filing_id, record_seq, box_values, amount)
  VALUES (f.tenant_id, v_id, 1, jsonb_build_object('taxable_sales', f.taxable_sales, 'exempt_sales', f.exempt_sales,
          'tax_collected', f.tax_collected, 'adjustments', f.adjustments, 'amount_due', f.amount_due), f.amount_due);
  RETURN v_id;
END $$;

-- @seq 395
CREATE FUNCTION public.efile_claim(p_limit integer DEFAULT 10) RETURNS SETOF public.efile_filings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY UPDATE efile_filings f SET status = 'transmitting', updated_at = now()
    WHERE f.id IN (SELECT id FROM efile_filings WHERE status = 'queued' ORDER BY created_at LIMIT p_limit FOR UPDATE SKIP LOCKED)
    RETURNING f.*;
END $$;

-- @seq 396
CREATE FUNCTION public.efile_mark_filed_manually(p_filing_id uuid, p_confirmation text, p_filed_at timestamp with time zone DEFAULT now()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f efile_filings%ROWTYPE;
BEGIN
  SELECT * INTO f FROM efile_filings WHERE id = p_filing_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown filing %', p_filing_id; END IF;
  IF NOT (platform_is_tenant_admin(f.tenant_id) OR auth.role() = 'service_role') THEN RAISE EXCEPTION 'Only an owner or admin can record a filing'; END IF;
  IF coalesce(trim(p_confirmation),'') = '' THEN RAISE EXCEPTION 'Confirmation number is required'; END IF;
  IF f.status NOT IN ('ready','draft') THEN RAISE EXCEPTION 'Filing is %', f.status; END IF;
  UPDATE efile_filings SET status = 'filed_manually', confirmation_number = p_confirmation, filed_at = p_filed_at, updated_at = now() WHERE id = f.id;
  UPDATE efile_filing_records SET status = 'accepted' WHERE filing_id = f.id;
  UPDATE acct_tax_filings SET status = CASE WHEN status = 'paid' THEN status ELSE 'filed' END, filed_at = p_filed_at, confirmation_ref = p_confirmation
   WHERE id = f.tax_filing_id;
  UPDATE acct_payroll_tax_forms p SET status = 'filed', filed_at = p_filed_at, confirmation_number = p_confirmation, updated_at = now()
    FROM efile_filing_records r WHERE r.filing_id = f.id AND r.source_form_id = p.id;
END $$;

-- @seq 397
CREATE FUNCTION public.efile_queue(p_filing_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f efile_filings%ROWTYPE; v_ret uuid;
BEGIN
  SELECT * INTO f FROM efile_filings WHERE id = p_filing_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown filing %', p_filing_id; END IF;
  IF NOT (platform_is_tenant_admin(f.tenant_id) OR auth.role() = 'service_role') THEN RAISE EXCEPTION 'Only an owner or admin can approve a filing'; END IF;
  IF f.channel = 'mef' THEN
    SELECT id INTO v_ret FROM mef_returns WHERE efile_filing_id = f.id;
    IF v_ret IS NULL THEN RAISE EXCEPTION 'No MeF return is linked to this filing'; END IF;
    RETURN mef_queue_return(v_ret);
  END IF;
  IF f.status <> 'ready' THEN RAISE EXCEPTION 'Filing is %, not ready', f.status; END IF;
  IF f.channel IN ('state_portal','manual') THEN
    RAISE EXCEPTION 'This state is filed on the state portal; file it there and record it with efile_mark_filed_manually()';
  END IF;
  IF f.channel = 'iris_a2a' AND NOT EXISTS (
       SELECT 1 FROM efile_transmitter_credentials c
        WHERE c.channel = 'iris_a2a' AND c.environment = f.environment AND (c.tenant_id = f.tenant_id OR c.tenant_id IS NULL)
          AND c.status IN ('active','testing') AND (f.environment = 'ats' OR (c.status = 'active' AND c.ats_passed_at IS NOT NULL))) THEN
    RAISE EXCEPTION 'No % IRIS transmitter credential (TCC + API Client ID%) is set up', f.environment,
      CASE WHEN f.environment = 'production' THEN ', ATS passed' ELSE '' END;
  END IF;
  UPDATE efile_filings SET status = 'queued', updated_at = now() WHERE id = f.id;
  RETURN 'queued';
END $$;

-- @seq 398
CREATE FUNCTION public.efile_record_acknowledgement(p_submission_id uuid, p_status text, p_raw jsonb DEFAULT '{}'::jsonb, p_errors jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s efile_submissions%ROWTYPE; v_ack uuid; e jsonb; v_rec uuid;
BEGIN
  SELECT * INTO s FROM efile_submissions WHERE id = p_submission_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown submission %', p_submission_id; END IF;
  INSERT INTO efile_acknowledgements(tenant_id, submission_id, ack_status, raw) VALUES (s.tenant_id, s.id, p_status, p_raw) RETURNING id INTO v_ack;
  FOR e IN SELECT * FROM jsonb_array_elements(coalesce(p_errors,'[]')) LOOP
    SELECT id INTO v_rec FROM efile_filing_records
     WHERE filing_id = s.filing_id AND ((e ? 'record_seq' AND record_seq = (e->>'record_seq')::int) OR (e ? 'irs_record_id' AND irs_record_id = e->>'irs_record_id'))
     LIMIT 1;
    INSERT INTO efile_errors(tenant_id, acknowledgement_id, filing_record_id, irs_record_id, error_code, element_path, message, severity)
    VALUES (s.tenant_id, v_ack, v_rec, e->>'irs_record_id', e->>'error_code', e->>'element_path', coalesce(e->>'message','(no message)'),
            coalesce(e->>'severity','reject'));
    IF v_rec IS NOT NULL AND coalesce(e->>'severity','reject') = 'reject' THEN
      UPDATE efile_filing_records SET status = 'rejected' WHERE id = v_rec;
    END IF;
  END LOOP;
  IF p_status = 'processing' THEN RETURN v_ack; END IF;
  UPDATE efile_filing_records SET status = 'accepted'
   WHERE filing_id = s.filing_id AND status = 'pending' AND p_status IN ('accepted','accepted_with_errors','partially_accepted');
  IF p_status = 'rejected' THEN UPDATE efile_filing_records SET status = 'rejected' WHERE filing_id = s.filing_id AND status = 'pending'; END IF;
  UPDATE efile_filings SET status = p_status, filed_at = CASE WHEN p_status <> 'rejected' THEN now() END,
         confirmation_number = coalesce(s.receipt_id, confirmation_number), updated_at = now() WHERE id = s.filing_id;
  UPDATE acct_payroll_tax_forms f SET status = CASE WHEN r.status = 'accepted' THEN 'accepted' ELSE 'rejected' END,
         filed_at = now(), confirmation_number = s.receipt_id, updated_at = now()
    FROM efile_filing_records r WHERE r.filing_id = s.filing_id AND r.source_form_id = f.id AND r.status IN ('accepted','rejected');
  UPDATE acct_tax_filings t SET status = CASE WHEN t.status = 'paid' THEN t.status ELSE 'filed' END, filed_at = now(), confirmation_ref = s.receipt_id
    FROM efile_filings ef WHERE ef.id = s.filing_id AND ef.tax_filing_id = t.id AND p_status <> 'rejected';
  RETURN v_ack;
END $$;

-- @seq 399
CREATE FUNCTION public.efile_record_submission(p_filing_id uuid, p_credential_id uuid, p_utid text, p_receipt_id text, p_http_status integer, p_response jsonb, p_payload_path text DEFAULT NULL::text, p_payload_sha256 text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f efile_filings%ROWTYPE; v_id uuid; v_ok boolean := p_http_status BETWEEN 200 AND 299;
BEGIN
  SELECT * INTO f FROM efile_filings WHERE id = p_filing_id FOR UPDATE;
  INSERT INTO efile_submissions(tenant_id, filing_id, credential_id, environment, attempt, utid, receipt_id, payload_storage_path, payload_sha256,
                                http_status, response, status)
  VALUES (f.tenant_id, f.id, p_credential_id, f.environment,
          1 + (SELECT count(*) FROM efile_submissions WHERE filing_id = f.id), p_utid, p_receipt_id, p_payload_path, p_payload_sha256,
          p_http_status, p_response, CASE WHEN v_ok THEN 'received' ELSE 'failed' END)
  RETURNING id INTO v_id;
  UPDATE efile_filings SET status = CASE WHEN v_ok THEN 'submitted' ELSE 'ready' END, updated_at = now() WHERE id = f.id;
  RETURN v_id;
END $$;

-- @seq 444
CREATE FUNCTION public.mef__aba_ok(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE d int[]; s int;
BEGIN
  IF p IS NULL OR p !~ '^[0-9]{9}$' THEN RETURN false; END IF;
  IF NOT (substr(p,1,2)::int BETWEEN 1 AND 12 OR substr(p,1,2)::int BETWEEN 21 AND 32 OR substr(p,1,2)::int BETWEEN 61 AND 72 OR substr(p,1,2) = '80') THEN RETURN false; END IF;
  SELECT array_agg(substr(p,i,1)::int ORDER BY i) INTO d FROM generate_series(1,9) i;
  s := 3*(d[1]+d[4]+d[7]) + 7*(d[2]+d[5]+d[8]) + (d[3]+d[6]+d[9]);
  RETURN s % 10 = 0;
END $_$;

