$$;

-- @seq 447
CREATE FUNCTION public.mef__headline(p_balance numeric, p_over numeric, p_total numeric, p_total_label text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_balance > 0 THEN jsonb_build_object('headline_amount', p_balance, 'headline_label', 'Balance due')
              WHEN p_over > 0 THEN jsonb_build_object('headline_amount', p_over, 'headline_label', 'Overpayment')
              ELSE jsonb_build_object('headline_amount', p_total, 'headline_label', p_total_label) END;
$$;

-- @seq 448
CREATE FUNCTION public.mef__incident_due_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE d date;
BEGIN
  IF NEW.confirmed_at IS NOT NULL AND (TG_OP = 'INSERT' OR OLD.confirmed_at IS DISTINCT FROM NEW.confirmed_at) THEN
    d := (NEW.confirmed_at AT TIME ZONE 'America/New_York')::date + 1;
    WHILE extract(isodow FROM d) > 5 LOOP d := d + 1; END LOOP;
    NEW.irs_report_due_at := (d + time '23:59') AT TIME ZONE 'America/New_York';
    IF NEW.status = 'open' THEN NEW.status := 'confirmed'; END IF;
  END IF;
  RETURN NEW;
END $$;

-- @seq 449
CREATE FUNCTION public.mef__pdf_name_ok(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT p IS NOT NULL AND length(p) <= 64 AND p ~ '^[A-Za-z0-9 ._-]+\.pdf$';
$_$;

-- @seq 450
CREATE FUNCTION public.mef__queue_issues(p_return_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE; f mef_form_families%ROWTYPE; sg mef_signatures%ROWTYPE; pv mef_providers%ROWTYPE; v text[] := '{}';
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id;
  IF NOT FOUND THEN RETURN ARRAY['Unknown return']; END IF;
  SELECT * INTO f FROM mef_form_families WHERE code = r.form_family;
  IF NOT f.is_enabled THEN v := array_append(v, ('Form family ' || f.code || ' is not enabled for e-file yet')); END IF;
  IF r.status NOT IN ('signed','rejected') THEN v := array_append(v, ('Return is ' || r.status || '; it must be signed first')); END IF;
  v := v || r.blocking_issues;
  SELECT * INTO sg FROM mef_signatures WHERE return_id = r.id AND status = 'valid';
  IF NOT FOUND THEN v := array_append(v, 'No valid signature: the return was never signed or changed after signing');
  ELSE
    IF sg.return_sha256 <> r.return_sha256 OR sg.return_version <> r.version THEN v := array_append(v, 'The signature does not match the current return'); END IF;
    IF sg.method = 'practitioner_pin' AND sg.ero_signed_at IS NULL THEN v := array_append(v, 'The ERO has not signed Form 8879 with the ERO PIN'); END IF;
    IF sg.efw_amount IS NOT NULL AND sg.efw_settlement_date < current_date THEN v := array_append(v, 'The withdrawal date has passed; set a new date and sign again'); END IF;
  END IF;
  SELECT * INTO pv FROM mef_providers WHERE id = r.provider_id;
  IF NOT FOUND THEN v := array_append(v, 'No e-file provider (EFIN/ETIN) is set up');
  ELSE
    IF pv.status <> 'accepted' THEN v := array_append(v, ('The IRS e-file application is ' || pv.status || ', not accepted')); END IF;
    IF NOT 'transmitter' = ANY (pv.roles) THEN v := array_append(v, 'The provider is not an accepted Transmitter'); END IF;
    IF pv.cert_secret_id IS NULL THEN v := array_append(v, 'No A2A certificate on file'); END IF;
    IF pv.cert_expires_at IS NOT NULL AND pv.cert_expires_at < now() THEN v := array_append(v, 'The A2A certificate has expired'); END IF;
    IF r.environment = 'production' THEN
      IF NOT EXISTS (SELECT 1 FROM mef_ats_status a WHERE a.provider_id = pv.id AND a.form_family = r.form_family
                       AND a.tax_year = r.tax_year AND a.status = 'passed') THEN
        v := array_append(v, ('ATS testing not passed for ' || r.form_family || ' tax year ' || r.tax_year));
      END IF;
      IF NOT EXISTS (SELECT 1 FROM mef_schema_versions s WHERE s.form_family = r.form_family AND s.tax_year = r.tax_year
                       AND s.production_start <= current_date AND coalesce(s.production_end, 'infinity') >= current_date) THEN
        v := array_append(v, ('No IRS schema version in production for ' || r.form_family || ' ' || r.tax_year));
      END IF;
      v := v || coalesce((SELECT array_agg('Control not verified: ' || c.code ORDER BY c.code) FROM mef_compliance_controls c
                           WHERE c.required_for IN ('production','all') AND c.status <> 'verified'), '{}');
    END IF;
  END IF;
  IF mef__efile_paused() THEN v := array_append(v, 'E-file is paused because of an open security incident'); END IF;
  IF EXISTS (SELECT 1 FROM mef_submissions s WHERE s.return_id = r.id AND s.status = 'accepted') THEN v := array_append(v, 'This return was already accepted'); END IF;
  RETURN v;
END $$;

-- @seq 451
CREATE FUNCTION public.mef__queue_issues_for_claim(p_return_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(array_agg(x), '{}') FROM unnest(mef__queue_issues(p_return_id)) x WHERE x NOT LIKE 'Return is %';
$$;

-- @seq 452
CREATE FUNCTION public.mef__rand_alnum(n integer) RETURNS text
    LANGUAGE sql
    AS $$
  SELECT string_agg(substr('abcdefghijklmnopqrstuvwxyz0123456789', 1 + (get_byte(b, i) % 36), 1), '')
    FROM (SELECT gen_random_bytes(n) b) x, generate_series(0, n - 1) i;
$$;

-- @seq 453
CREATE FUNCTION public.mef__return_after_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.version <> OLD.version THEN
    INSERT INTO mef_return_versions(tenant_id, return_id, version, return_sha256, return_data, summary, efw, changed_by)
    VALUES (NEW.tenant_id, NEW.id, NEW.version, NEW.return_sha256, NEW.return_data, NEW.summary, NEW.efw, auth.uid())
    ON CONFLICT (return_id, version) DO NOTHING;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.version <> OLD.version THEN
    UPDATE mef_signatures SET status = 'void_edited', voided_at = now() WHERE return_id = NEW.id AND status = 'valid';
    UPDATE tax_screen_presentations SET expires_at = least(expires_at, now()) WHERE return_id = NEW.id AND used_at IS NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.efile_filing_id IS NOT NULL AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE efile_filings SET status = CASE NEW.status
        WHEN 'draft' THEN 'draft' WHEN 'awaiting_signature' THEN 'draft' WHEN 'signed' THEN 'ready'
        WHEN 'queued' THEN 'queued' WHEN 'transmitting' THEN 'transmitting' WHEN 'submitted' THEN 'submitted'
        WHEN 'accepted' THEN 'accepted' WHEN 'rejected' THEN 'rejected' ELSE 'void' END,
      total_amount = NEW.balance_due, filed_at = CASE WHEN NEW.status = 'accepted' THEN NEW.accepted_at ELSE filed_at END,
      updated_at = now()
     WHERE id = NEW.efile_filing_id;
  END IF;
  RETURN NULL;
END $$;

-- @seq 454
CREATE FUNCTION public.mef__return_before_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_hash text;
BEGIN
  v_hash := mef__return_hash(NEW);
  IF TG_OP = 'INSERT' THEN
    NEW.return_sha256 := v_hash; NEW.version := 1; RETURN NEW;
  END IF;
  IF NEW.tenant_id <> OLD.tenant_id OR NEW.entity_id <> OLD.entity_id OR NEW.form_family <> OLD.form_family THEN
    RAISE EXCEPTION 'A return cannot move to another tenant, entity or form family';
  END IF;
  IF v_hash IS DISTINCT FROM OLD.return_sha256 THEN
    IF OLD.status IN ('transmitting','submitted','accepted','void') THEN
      RAISE EXCEPTION 'This return is % and cannot be changed; file an amended return instead', OLD.status;
    END IF;
    NEW.return_sha256 := v_hash;
    NEW.version := OLD.version + 1;
    IF OLD.status IN ('signed','queued','rejected') THEN NEW.status := 'awaiting_signature'; END IF;
  ELSE
    NEW.return_sha256 := OLD.return_sha256; NEW.version := OLD.version;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- @seq 456
CREATE FUNCTION public.mef__return_hash(r public.mef_returns) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'entity', r.entity_id, 'form', r.form_code, 'year', r.tax_year, 'period', r.period_label, 'start', r.period_start, 'end', r.period_end,
    'data', r.return_data, 'summary', r.summary, 'balance_due', r.balance_due, 'overpayment', r.overpayment,
    'efw', coalesce(r.efw - 'account_secret_id', 'null'::jsonb), 'ero', r.ero_involved)::text, 'UTF8')), 'hex');
$$;

-- @seq 457
CREATE FUNCTION public.mef__signature_immutable_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Signatures are kept as evidence and cannot be deleted'; END IF;
  IF (to_jsonb(NEW) - ARRAY['status','voided_at','ero_pin_secret_id','ero_signer_id','ero_signed_at'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','voided_at','ero_pin_secret_id','ero_signer_id','ero_signed_at']) THEN
    RAISE EXCEPTION 'A signature cannot be altered';
  END IF;
  IF OLD.status <> 'valid' AND NEW.status <> OLD.status THEN RAISE EXCEPTION 'A % signature cannot be reinstated', OLD.status; END IF;
  IF OLD.ero_signed_at IS NOT NULL AND NEW.ero_signed_at IS DISTINCT FROM OLD.ero_signed_at THEN RAISE EXCEPTION 'The ERO already signed'; END IF;
  RETURN NEW;
END $$;

-- @seq 458
CREATE FUNCTION public.mef__submission_id_ok(p_id text, p_efin text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
  SELECT p_id ~ '^[0-9]{13}[a-z0-9]{7}$' AND left(p_id, 6) = p_efin
     AND substr(p_id, 7, 4)::int = extract(year FROM current_date)::int
     AND substr(p_id, 11, 3)::int BETWEEN 1 AND extract(doy FROM make_date(extract(year FROM current_date)::int, 12, 31))::int;
$_$;

-- @seq 459
CREATE FUNCTION public.mef_build_941(p_tenant_id uuid, p_tax_year integer, p_quarter integer, p_deposits numeric DEFAULT 0, p_depositor text DEFAULT 'monthly'::text, p_overpayment_choice text DEFAULT 'apply_next'::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c mef_payroll_constants%ROWTYPE; v_start date; v_end date; v_ref date; v_entity uuid; v_label text;
  l1 int; l2 numeric; l3 numeric; w5a numeric; t5b numeric; m5c numeric; m5d numeric;
  t5a numeric; t5bt numeric; t5c numeric; t5d numeric; l5e numeric; l6 numeric; l7 numeric; l10 numeric; l12 numeric; l13 numeric; l14 numeric; l15 numeric;
  actual_fica numeric; v_items int; v_pretax numeric; m1 numeric; m2 numeric; m3 numeric; v_warn text[] := '{}'; v_block text[] := '{}';
  v_data jsonb; v_summary jsonb; v_id uuid; r mef_returns%ROWTYPE;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  IF p_quarter NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Quarter is 1 to 4'; END IF;
  IF p_depositor NOT IN ('monthly','semiweekly') THEN RAISE EXCEPTION 'Depositor schedule is monthly or semiweekly'; END IF;
  IF p_overpayment_choice NOT IN ('apply_next','refund') THEN RAISE EXCEPTION 'Overpayment choice is apply_next or refund'; END IF;
  IF coalesce(p_deposits,0) < 0 THEN RAISE EXCEPTION 'Deposits cannot be negative'; END IF;
  SELECT * INTO c FROM mef_payroll_constants WHERE tax_year = p_tax_year;
  IF NOT FOUND THEN RAISE EXCEPTION 'No payroll constants for % (Social Security wage base); load them first', p_tax_year; END IF;
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  v_start := make_date(p_tax_year, (p_quarter - 1) * 3 + 1, 1);
  v_end := (v_start + interval '3 months' - interval '1 day')::date;
  v_ref := make_date(p_tax_year, p_quarter * 3, 12);
  v_label := 'Q' || p_quarter || ' ' || p_tax_year;

  CREATE TEMP TABLE IF NOT EXISTS _m941 (employee_id uuid, pay_date date, gross numeric, tips numeric, fit numeric, fica numeric, pretax numeric, period_start date, period_end date) ON COMMIT DROP;
  TRUNCATE _m941;
  INSERT INTO _m941
  SELECT i.employee_id, pp.pay_date, coalesce(i.gross_pay,0), coalesce(i.tips_pay,0), coalesce(i.federal_income_tax,0),
         coalesce(i.social_security_ee,0) + coalesce(i.medicare_ee,0) + coalesce(i.social_security_er,0) + coalesce(i.medicare_er,0),
         coalesce(i.pretax_deductions,0), pp.period_start, pp.period_end
    FROM acct_payroll_run_items i JOIN acct_payroll_runs pr ON pr.id = i.payroll_run_id JOIN acct_pay_periods pp ON pp.id = pr.pay_period_id
   WHERE pr.tenant_id = p_tenant_id AND pp.pay_date BETWEEN make_date(p_tax_year,1,1) AND v_end
     AND (pr.gl_journal_entry_id IS NOT NULL OR pr.status IN ('approved','submitted','paid'));

  SELECT count(*), coalesce(sum(gross),0), coalesce(sum(fit),0), coalesce(sum(fica),0), coalesce(sum(pretax),0)
    INTO v_items, l2, l3, actual_fica, v_pretax FROM _m941 WHERE pay_date >= v_start;
  IF v_items = 0 THEN RAISE EXCEPTION 'No posted payroll with a pay date in %', v_label; END IF;

  -- per employee, year to date, so the wage base and the 200,000 threshold are applied correctly
  WITH e AS (
    SELECT employee_id,
           sum(gross) FILTER (WHERE pay_date < v_start) prior_gross,
           sum(gross - tips) FILTER (WHERE pay_date >= v_start) q_wages,
           sum(tips) FILTER (WHERE pay_date >= v_start) q_tips,
           sum(gross) FILTER (WHERE pay_date >= v_start) q_gross
      FROM _m941 GROUP BY employee_id),
  k AS (
    SELECT *, greatest(0, c.ss_wage_base - coalesce(prior_gross,0)) room FROM e WHERE coalesce(q_gross,0) <> 0)
  SELECT coalesce(sum(least(coalesce(q_wages,0), room)),0),
         coalesce(sum(least(coalesce(q_tips,0), greatest(0, room - least(coalesce(q_wages,0), room)))),0),
         coalesce(sum(q_gross),0),
         coalesce(sum(greatest(0, coalesce(prior_gross,0) + q_gross - c.addl_medicare_threshold) - greatest(0, coalesce(prior_gross,0) - c.addl_medicare_threshold)),0)
    INTO w5a, t5b, m5c, m5d FROM k;

  SELECT count(DISTINCT employee_id) INTO l1 FROM _m941 WHERE v_ref BETWEEN period_start AND period_end;
  IF l1 = 0 THEN
    SELECT count(DISTINCT employee_id) INTO l1 FROM _m941 WHERE pay_date >= v_start;
    v_warn := array_append(v_warn, 'Line 1: no pay period includes ' || to_char(v_ref,'Mon DD') || '; counted everyone paid in the quarter. Confirm the count.');
  END IF;
  t5a := round(w5a * c.ss_rate_combined, 2);
  t5bt := round(t5b * c.ss_rate_combined, 2);
  t5c := round(m5c * c.medicare_rate_combined, 2);
  t5d := round(m5d * c.addl_medicare_rate, 2);
  l5e := t5a + t5bt + t5c + t5d;
  l6 := l3 + l5e;
  -- line 7: fractions of cents only; anything bigger is a payroll error, not an adjustment
  l7 := round(actual_fica - (t5a + t5bt + t5c), 2);
  IF abs(l7) > 0.01 * greatest(v_items, 1) * 4 THEN
    v_warn := array_append(v_warn, format('Social Security and Medicare withheld plus employer share (%s) differ from line 5e (%s) by more than rounding; line 7 left at 0. Check payroll.', actual_fica, t5a + t5bt + t5c));
    l7 := 0;
  END IF;
  l10 := l6 + l7;
  l12 := l10;                                         -- line 11 credits: none computed
  l13 := round(coalesce(p_deposits,0), 2);
  l14 := greatest(0, l12 - l13);
  l15 := greatest(0, l13 - l12);
  IF v_pretax > 0 THEN
    v_warn := array_append(v_warn, 'Pre-tax deductions exist. Section 125 (cafeteria) deductions reduce Social Security and Medicare wages; 401(k) deferrals do not. Confirm lines 5a and 5c.');
  END IF;
  -- monthly liabilities (line 16), trued up so the months add to line 12
  SELECT coalesce(sum(fit + fica) FILTER (WHERE extract(month FROM pay_date) = (p_quarter-1)*3+1),0),
         coalesce(sum(fit + fica) FILTER (WHERE extract(month FROM pay_date) = (p_quarter-1)*3+2),0),
         coalesce(sum(fit + fica) FILTER (WHERE extract(month FROM pay_date) = (p_quarter-1)*3+3),0)
    INTO m1, m2, m3 FROM _m941 WHERE pay_date >= v_start;
  IF m3 <> 0 OR (m1 = 0 AND m2 = 0) THEN m3 := m3 + (l12 - (m1+m2+m3));
  ELSIF m2 <> 0 THEN m2 := m2 + (l12 - (m1+m2+m3)); ELSE m1 := m1 + (l12 - (m1+m2+m3)); END IF;
  IF l12 >= c.deposit_threshold AND p_depositor = 'semiweekly' THEN
    v_block := array_append(v_block, 'Semiweekly depositor: Schedule B (Form 941) is required and is not built yet.');
  END IF;
  IF l12 < c.deposit_threshold THEN
    v_warn := array_append(v_warn, 'Line 16 box 1 assumes the prior-quarter liability was also under 2,500 (or no 100,000 next-day obligation). Confirm.');
  END IF;
  IF l15 > 0 AND p_overpayment_choice = 'refund' THEN
    v_block := array_append(v_block, 'Refund by direct deposit (lines 15b-15e) needs the bank details; add them or choose apply to next return.');
  END IF;

  v_data := jsonb_build_object('form','941','revision','2026-03','quarter',p_quarter,'tax_year',p_tax_year,
    'line_1', l1, 'line_2', l2, 'line_3', l3, 'line_4', l5e = 0,
    'line_5a', jsonb_build_object('wages', w5a, 'tax', t5a), 'line_5b', jsonb_build_object('wages', t5b, 'tax', t5bt),
    'line_5c', jsonb_build_object('wages', m5c, 'tax', t5c), 'line_5d', jsonb_build_object('wages', m5d, 'tax', t5d),
    'line_5e', l5e, 'line_5f', 0, 'line_6', l6, 'line_7', l7, 'line_8', 0, 'line_9', 0, 'line_10', l10, 'line_11', 0,
    'line_12', l12, 'line_13', l13, 'line_14', l14, 'line_15', l15, 'line_15_choice', CASE WHEN l15 > 0 THEN p_overpayment_choice END,
    'line_16', CASE WHEN l12 < c.deposit_threshold THEN jsonb_build_object('box', 1)
                    WHEN p_depositor = 'monthly' THEN jsonb_build_object('box', 2, 'month_1', m1, 'month_2', m2, 'month_3', m3, 'total', m1+m2+m3)
                    ELSE jsonb_build_object('box', 3) END,
    'source', jsonb_build_object('payroll_items', v_items, 'built_at', now()));
  v_summary := mef__headline(l14, l15, l12, 'Total taxes after adjustments and credits') || jsonb_build_object('part_i', jsonb_build_array(
    jsonb_build_object('line','2','label','Wages, tips and other compensation','amount',l2),
    jsonb_build_object('line','10','label','Total taxes after adjustments','amount',l10),
    jsonb_build_object('line','12','label','Total taxes after adjustments and nonrefundable credits','amount',l12),
    jsonb_build_object('line','13','label','Total deposits for this quarter','amount',l13),
    jsonb_build_object('line','14','label','Balance due','amount',l14),
    jsonb_build_object('line','15','label','Overpayment','amount',l15)));

  SELECT * INTO r FROM mef_returns WHERE entity_id = v_entity AND form_code = '941' AND tax_year = p_tax_year AND period_label = v_label AND status <> 'void' FOR UPDATE;
  IF FOUND THEN
    IF r.status IN ('transmitting','submitted','accepted') THEN RAISE EXCEPTION 'The % Form 941 is already %; a change needs Form 941-X', v_label, r.status; END IF;
    UPDATE mef_returns SET return_data = v_data, summary = v_summary, balance_due = l14, overpayment = l15, warnings = v_warn, blocking_issues = v_block,
           efw = CASE WHEN l14 > 0 AND (efw->>'amount')::numeric <= 2 * l14 THEN efw END
     WHERE id = r.id;
    RETURN r.id;
  END IF;
  v_id := mef_create_return(p_tenant_id, '941', p_tax_year, v_label, v_start, v_end,
            (date_trunc('month', v_end + 1) + interval '1 month' - interval '1 day')::date, v_data, v_summary, l14, l15, v_entity);
  UPDATE mef_returns SET warnings = v_warn, blocking_issues = v_block WHERE id = v_id;
  RETURN v_id;
END $$;

-- @seq 460
CREATE FUNCTION public.mef_claim(p_limit integer DEFAULT 100, p_environment text DEFAULT 'production'::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE; sg mef_signatures%ROWTYPE; v text[];
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Worker only'; END IF;
  FOR r IN SELECT * FROM mef_returns WHERE status = 'queued' AND environment = p_environment
            ORDER BY due_date NULLS LAST, updated_at LIMIT least(greatest(p_limit,1),100) FOR UPDATE SKIP LOCKED LOOP
    v := mef__queue_issues_for_claim(r.id);
    IF cardinality(v) > 0 THEN
      UPDATE mef_returns SET status = CASE WHEN EXISTS (SELECT 1 FROM mef_signatures WHERE return_id = r.id AND status = 'valid') THEN 'signed' ELSE 'awaiting_signature' END,
             warnings = array_append(warnings, 'Held back at transmission: ' || array_to_string(v, '; ')) WHERE id = r.id;
      CONTINUE;
    END IF;
    SELECT * INTO sg FROM mef_signatures WHERE return_id = r.id AND status = 'valid';
    UPDATE mef_returns SET status = 'transmitting' WHERE id = r.id;
    RETURN NEXT jsonb_build_object('return_id', r.id, 'tenant_id', r.tenant_id, 'form_code', r.form_code, 'form_family', r.form_family,
      'tax_year', r.tax_year, 'period', r.period_label, 'version', r.version, 'return_sha256', r.return_sha256, 'return_data', r.return_data,
      'efw', r.efw, 'provider_id', r.provider_id, 'environment', r.environment,
      'signature', jsonb_build_object('id', sg.id, 'method', sg.method, 'irs_form', sg.irs_form, 'signer_name', sg.signer_name, 'signer_title', sg.signer_title,
         'signed_at', sg.signed_at, 'taxpayer_pin_secret_id', sg.taxpayer_pin_secret_id, 'online_pin_secret_id', sg.online_pin_secret_id,
         'ero_pin_secret_id', sg.ero_pin_secret_id, 'scanned_pdf_path', sg.scanned_pdf_path));
  END LOOP;
END $$;

-- @seq 461
CREATE FUNCTION public.mef_create_return(p_tenant_id uuid, p_form_code text, p_tax_year integer, p_period_label text, p_period_start date, p_period_end date, p_due_date date, p_return_data jsonb, p_summary jsonb, p_balance_due numeric DEFAULT 0, p_overpayment numeric DEFAULT 0, p_entity_id uuid DEFAULT NULL::uuid, p_ero_involved boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_family text; v_entity uuid; v_id uuid; v_filing uuid; v_provider uuid;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  v_family := mef__family_for(p_form_code);
  IF v_family IS NULL THEN RAISE EXCEPTION 'Form % is not an MeF form', p_form_code; END IF;
  IF p_summary->>'headline_amount' IS NULL THEN RAISE EXCEPTION 'The summary needs headline_amount and headline_label (what the signer confirms)'; END IF;
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  IF NOT EXISTS (SELECT 1 FROM acct_entities WHERE id = v_entity AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Unknown entity'; END IF;
  SELECT id INTO v_provider FROM mef_providers WHERE (tenant_id = p_tenant_id OR tenant_id IS NULL) AND 'transmitter' = ANY (roles)
   ORDER BY (tenant_id IS NULL), created_at LIMIT 1;
  IF EXISTS (SELECT 1 FROM efile_form_types WHERE code = p_form_code) THEN
    INSERT INTO efile_filings(tenant_id, entity_id, form_code, tax_year, period_label, period_start, period_end, due_date, channel, status, total_amount, created_by)
    VALUES (p_tenant_id, v_entity, p_form_code, p_tax_year, p_period_label, p_period_start, p_period_end, p_due_date, 'mef', 'draft', p_balance_due, auth.uid())
    RETURNING id INTO v_filing;
  END IF;
  INSERT INTO mef_returns(tenant_id, entity_id, efile_filing_id, form_family, form_code, tax_year, period_label, period_start, period_end, due_date,
                          ero_involved, provider_id, status, return_data, summary, balance_due, overpayment, created_by)
  VALUES (p_tenant_id, v_entity, v_filing, v_family, p_form_code, p_tax_year, p_period_label, p_period_start, p_period_end, p_due_date,
          p_ero_involved, v_provider, 'awaiting_signature', p_return_data, p_summary, p_balance_due, p_overpayment, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;

-- @seq 462
CREATE FUNCTION public.mef_ero_certify(p_signature_id uuid, p_ero_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE sg mef_signatures%ROWTYPE; r mef_returns%ROWTYPE; e mef_signers%ROWTYPE; v_efin text;
BEGIN
  SELECT * INTO sg FROM mef_signatures WHERE id = p_signature_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown signature'; END IF;
  PERFORM acct_assert_access(sg.tenant_id);
  IF sg.status <> 'valid' THEN RAISE EXCEPTION 'This signature is %; the taxpayer must sign again', sg.status; END IF;
  IF sg.method <> 'practitioner_pin' THEN RAISE EXCEPTION 'ERO certification applies only to the Practitioner PIN method'; END IF;
  SELECT * INTO r FROM mef_returns WHERE id = sg.return_id;
  IF r.return_sha256 <> sg.return_sha256 THEN RAISE EXCEPTION 'The return changed after the taxpayer signed'; END IF;
  SELECT * INTO e FROM mef_signers WHERE entity_id = r.entity_id AND user_id = auth.uid() AND role = 'ero' AND is_authorized_signer;
  IF NOT FOUND THEN RAISE EXCEPTION 'Only the ERO for this business can certify the return'; END IF;
  SELECT efin INTO v_efin FROM mef_providers WHERE id = r.provider_id;
  IF v_efin IS NULL THEN RAISE EXCEPTION 'No EFIN on the provider for this return'; END IF;
  IF p_ero_pin IS NULL OR p_ero_pin !~ '^[0-9]{11}$' OR left(p_ero_pin, 6) <> v_efin OR right(p_ero_pin, 5) = '00000' THEN
    RAISE EXCEPTION 'The ERO PIN is your 6-digit EFIN followed by 5 digits that are not all zeros';
  END IF;
  UPDATE mef_signatures SET ero_pin_secret_id = platform__vault_store('mef_ero_pin', p_ero_pin, 'ERO PIN, return ' || r.id),
         ero_signer_id = e.id, ero_signed_at = now()
   WHERE id = sg.id;
END $_$;

-- @seq 463
CREATE FUNCTION public.mef_new_message_id(p_etin text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF p_etin !~ '^[0-9]{5}$' THEN RAISE EXCEPTION 'ETIN must be 5 digits'; END IF;
  RETURN p_etin || to_char(current_date, 'YYYY') || to_char(current_date, 'DDD') || mef__rand_alnum(8);
END $_$;

-- @seq 464
CREATE FUNCTION public.mef_new_submission_id(p_efin text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF p_efin !~ '^[0-9]{6}$' THEN RAISE EXCEPTION 'EFIN must be 6 digits'; END IF;
  RETURN p_efin || to_char(current_date, 'YYYY') || to_char(current_date, 'DDD') || mef__rand_alnum(7);
END $_$;

-- @seq 465
CREATE FUNCTION public.mef_queue_return(p_return_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE; v text[];
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  IF NOT (platform_is_tenant_admin(r.tenant_id) OR auth.role() = 'service_role') THEN RAISE EXCEPTION 'Only an owner or admin can send a return to the IRS'; END IF;
  v := mef__queue_issues(r.id);
  IF cardinality(v) > 0 THEN RAISE EXCEPTION 'Not sent: %', array_to_string(v, '; '); END IF;
  UPDATE mef_returns SET status = 'queued' WHERE id = r.id;
  RETURN 'queued';
END $$;

-- @seq 466
CREATE FUNCTION public.mef_readiness(p_family text DEFAULT '94x'::text, p_tax_year integer DEFAULT (EXTRACT(year FROM CURRENT_DATE))::integer) RETURNS TABLE(item text, status text, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE pv mef_providers%ROWTYPE;
BEGIN
  IF NOT (auth.role() = 'service_role' OR platform_is_admin()) THEN RAISE EXCEPTION 'Platform staff only'; END IF;
  SELECT * INTO pv FROM mef_providers WHERE tenant_id IS NULL AND 'transmitter' = ANY (roles) ORDER BY created_at LIMIT 1;
  item := 'IRS e-file application (Pub 3112)';
  status := CASE WHEN pv.id IS NULL THEN 'missing' WHEN pv.status = 'accepted' THEN 'ok' ELSE 'pending' END;
  detail := coalesce('status ' || pv.status || ', roles ' || array_to_string(pv.roles, ','), 'No Unsaid provider row; apply in e-Services'); RETURN NEXT;
  item := 'EFIN'; status := CASE WHEN pv.efin IS NOT NULL THEN 'ok' ELSE 'missing' END; detail := NULL; RETURN NEXT;
  item := 'ETIN (transmitter/software developer)'; status := CASE WHEN pv.etin IS NOT NULL THEN 'ok' ELSE 'missing' END; RETURN NEXT;
  item := 'A2A certificate'; status := CASE WHEN pv.cert_secret_id IS NULL THEN 'missing' WHEN pv.cert_expires_at < now() + interval '30 days' THEN 'expiring' ELSE 'ok' END;
  detail := 'expires ' || coalesce(pv.cert_expires_at::date::text, '?'); RETURN NEXT;
  item := 'ATS passed (' || p_family || ' ' || p_tax_year || ')';
  status := CASE WHEN EXISTS (SELECT 1 FROM mef_ats_status a WHERE a.provider_id = pv.id AND a.form_family = p_family AND a.tax_year = p_tax_year AND a.status = 'passed') THEN 'ok' ELSE 'missing' END;
  detail := (SELECT 'Software ID ' || software_id FROM mef_ats_status a WHERE a.provider_id = pv.id AND a.form_family = p_family AND a.tax_year = p_tax_year); RETURN NEXT;
  item := 'Schema in production window';
  status := CASE WHEN EXISTS (SELECT 1 FROM mef_schema_versions s WHERE s.form_family = p_family AND s.tax_year = p_tax_year
                   AND s.production_start <= current_date AND coalesce(s.production_end,'infinity') >= current_date) THEN 'ok' ELSE 'missing' END;
  detail := NULL; RETURN NEXT;
  item := 'Form family enabled'; status := CASE WHEN (SELECT is_enabled FROM mef_form_families WHERE code = p_family) THEN 'ok' ELSE 'disabled' END; RETURN NEXT;
  RETURN QUERY SELECT 'Control: ' || c.code, CASE WHEN c.status = 'verified' AND (c.last_verified_at IS NULL OR c.last_verified_at > now() - make_interval(days => c.review_interval_days)) THEN 'ok'
                                               WHEN c.status = 'verified' THEN 'stale' ELSE c.status END, c.requirement
                 FROM mef_compliance_controls c ORDER BY c.code;
  item := 'Open security incident pausing e-file'; status := CASE WHEN mef__efile_paused() THEN 'blocked' ELSE 'ok' END; detail := NULL; RETURN NEXT;
END $$;

-- @seq 467
CREATE FUNCTION public.mef_record_ack(p_submission_id text, p_status text, p_ack_at timestamp with time zone, p_irs_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_errors jsonb DEFAULT '[]'::jsonb, p_raw_path text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s mef_submissions%ROWTYPE; r mef_returns%ROWTYPE; f mef_form_families%ROWTYPE; v_ack uuid; v_recv timestamptz; v_email text; v_mail uuid;
  v_first timestamptz; v_deadline timestamptz; v_fee mef_fee_schedule%ROWTYPE; v_subject text; v_text text;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Worker only'; END IF;
  IF p_status NOT IN ('accepted','rejected') THEN RAISE EXCEPTION 'Acknowledgement status is accepted or rejected'; END IF;
  SELECT * INTO s FROM mef_submissions WHERE submission_id = p_submission_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown submission %', p_submission_id; END IF;
  SELECT id INTO v_ack FROM mef_acknowledgements WHERE submission_id = s.id;
  IF FOUND THEN RETURN v_ack; END IF;                         -- acks are retrieved more than once; record once
  IF p_status = 'rejected' AND jsonb_array_length(coalesce(p_errors,'[]')) = 0 THEN RAISE EXCEPTION 'A rejection must carry its errors'; END IF;
  SELECT * INTO r FROM mef_returns WHERE id = s.return_id FOR UPDATE;
  SELECT * INTO f FROM mef_form_families WHERE code = r.form_family;
  v_recv := coalesce(p_irs_received_at, s.irs_received_at, p_ack_at);
  INSERT INTO mef_acknowledgements(tenant_id, submission_id, status, ack_at, irs_received_at, raw_path)
  VALUES (s.tenant_id, s.id, p_status, p_ack_at, v_recv, p_raw_path) RETURNING id INTO v_ack;
  INSERT INTO mef_ack_errors(tenant_id, ack_id, document_id, xpath, category, message, rule_number, severity, data_value)
  SELECT s.tenant_id, v_ack, e->>'document_id', e->>'xpath', e->>'category', coalesce(e->>'message','(no message)'), e->>'rule_number', e->>'severity', e->>'data_value'
    FROM jsonb_array_elements(coalesce(p_errors,'[]')) e;
  UPDATE mef_submissions SET status = p_status, irs_received_at = v_recv WHERE id = s.id;
  UPDATE mef_transmissions SET status = 'acknowledged' WHERE id = s.transmission_id
     AND NOT EXISTS (SELECT 1 FROM mef_submissions x WHERE x.transmission_id = s.transmission_id AND x.status = 'sent');

  IF p_status = 'rejected' THEN
    v_first := coalesce(r.first_rejected_at, v_recv);
    v_deadline := coalesce(r.perfection_deadline, v_first + make_interval(days => f.perfection_days));
    UPDATE mef_returns SET status = 'rejected', first_rejected_at = v_first, perfection_deadline = v_deadline WHERE id = r.id;
    v_subject := 'The IRS rejected your Form ' || r.form_code || ' for ' || r.period_label;
    v_text := 'The IRS rejected the return. Fix the items below and send it again by ' || to_char(v_deadline, 'Mon DD, YYYY') ||
              ' so it is treated as received on ' || to_char(v_first, 'Mon DD, YYYY') || E'.\n\n' ||
              coalesce((SELECT string_agg(coalesce(e->>'rule_number','') || ' ' || coalesce(e->>'message',''), E'\n') FROM jsonb_array_elements(p_errors) e), '');
  ELSE
    UPDATE mef_returns SET status = 'accepted', accepted_at = p_ack_at,
           deemed_received_at = CASE WHEN r.first_rejected_at IS NOT NULL AND v_recv <= r.perfection_deadline THEN r.first_rejected_at ELSE v_recv END
     WHERE id = r.id;
    SELECT * INTO v_fee FROM mef_fee_schedule WHERE form_family = r.form_family AND is_active ORDER BY fee_code LIMIT 1;
    INSERT INTO mef_billable_events(tenant_id, return_id, fee_code, amount) VALUES (r.tenant_id, r.id, v_fee.fee_code, coalesce(v_fee.amount, r.fee_amount))
    ON CONFLICT (return_id) DO NOTHING;
    v_subject := 'The IRS accepted your Form ' || r.form_code || ' for ' || r.period_label;
    v_text := 'The IRS accepted the return on ' || to_char(p_ack_at, 'Mon DD, YYYY') || '. Submission ID ' || s.submission_id || '.' ||
              CASE WHEN r.efw IS NOT NULL THEN E'\nPayment of ' || (r.efw->>'amount') || ' will be withdrawn on ' || (r.efw->>'settlement_date') ||
                   '. To cancel, call the U.S. Treasury Financial Agent at 1-888-353-4537 no later than 2 business days before that date.' ELSE '' END;
  END IF;
  -- Online Provider must tell the taxpayer within 2 business days (Pub 4163)
  SELECT u.email INTO v_email FROM mef_signatures sg JOIN auth.users u ON u.id = sg.signer_user_id WHERE sg.id = s.signature_id;
  BEGIN
    IF v_email IS NULL THEN RAISE EXCEPTION 'no signer email'; END IF;
    v_mail := email_enqueue(r.tenant_id, 'mef-ack-' || v_ack, app__default_from(r.tenant_id), ARRAY[v_email], v_subject, NULL, v_text,
                            'transactional', 'mef_returns', r.id);
    UPDATE mef_acknowledgements SET taxpayer_notified_email_id = v_mail WHERE id = v_ack;
  EXCEPTION WHEN OTHERS THEN
    UPDATE mef_acknowledgements SET taxpayer_notice_error = SQLERRM WHERE id = v_ack;
  END;
  RETURN v_ack;
END $$;

-- @seq 468
CREATE FUNCTION public.mef_record_transmission(p_provider_id uuid, p_environment text, p_message_id text, p_submissions jsonb, p_receipt_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE pv mef_providers%ROWTYPE; v_tx uuid; s jsonb; a jsonb; r mef_returns%ROWTYPE; sg mef_signatures%ROWTYPE; v_n int;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Worker only'; END IF;
  SELECT * INTO pv FROM mef_providers WHERE id = p_provider_id;
  IF NOT FOUND OR pv.etin IS NULL OR pv.efin IS NULL THEN RAISE EXCEPTION 'Provider needs an EFIN and ETIN'; END IF;
  v_n := jsonb_array_length(coalesce(p_submissions, '[]'));
  IF v_n NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'A transmission holds 1 to 100 submissions, got %', v_n; END IF;
  IF p_message_id !~ '^[0-9]{12}[a-z0-9]{8}$' OR left(p_message_id, 5) <> pv.etin
     OR substr(p_message_id, 6, 4)::int <> extract(year FROM current_date)::int THEN
    RAISE EXCEPTION 'Message ID % is not ETIN + current year + day + 8 characters', p_message_id;
  END IF;
  INSERT INTO mef_transmissions(provider_id, environment, message_id, submission_count, receipt_id, status, receipt_at)
  VALUES (pv.id, p_environment, p_message_id, v_n, p_receipt_id, CASE WHEN p_receipt_id IS NULL THEN 'sent' ELSE 'receipted' END,
          CASE WHEN p_receipt_id IS NOT NULL THEN now() END)
  RETURNING id INTO v_tx;
  FOR s IN SELECT * FROM jsonb_array_elements(p_submissions) LOOP
    SELECT * INTO r FROM mef_returns WHERE id = (s->>'return_id')::uuid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return %', s->>'return_id'; END IF;
    IF r.status <> 'transmitting' THEN RAISE EXCEPTION 'Return % is %, not claimed for transmission', r.id, r.status; END IF;
    IF r.provider_id <> pv.id OR r.environment <> p_environment THEN RAISE EXCEPTION 'Return % belongs to another provider or environment', r.id; END IF;
    IF s->>'return_sha256' IS DISTINCT FROM r.return_sha256 THEN RAISE EXCEPTION 'Return % changed after it was claimed; the serialized XML is not the signed return', r.id; END IF;
    IF NOT mef__submission_id_ok(s->>'submission_id', pv.efin) THEN RAISE EXCEPTION 'Submission ID % is not EFIN + current year + day + 7 characters', s->>'submission_id'; END IF;
    SELECT * INTO sg FROM mef_signatures WHERE return_id = r.id AND status = 'valid' AND return_sha256 = r.return_sha256;
    IF NOT FOUND THEN RAISE EXCEPTION 'Return % has no valid signature for this version', r.id; END IF;
    FOR a IN SELECT * FROM jsonb_array_elements(coalesce(s->'attachments', '[]')) LOOP
      IF NOT mef__pdf_name_ok(a->>'filename') THEN RAISE EXCEPTION 'Attachment name % must be a .pdf, 64 characters max, letters, digits, space . _ -', a->>'filename'; END IF;
      IF length(coalesce(a->>'description','')) > 128 THEN RAISE EXCEPTION 'Attachment description is over 128 characters'; END IF;
      IF coalesce((a->>'bytes')::bigint, 0) > 60 * 1024 * 1024 THEN RAISE EXCEPTION 'Attachment % is over 60 MB', a->>'filename'; END IF;
    END LOOP;
    INSERT INTO mef_submissions(tenant_id, return_id, signature_id, transmission_id, submission_id, return_version, return_sha256, xml_path, xml_sha256, attachments)
    VALUES (r.tenant_id, r.id, sg.id, v_tx, s->>'submission_id', r.version, r.return_sha256, s->>'xml_path', s->>'xml_sha256', coalesce(s->'attachments','[]'));
    UPDATE mef_returns SET status = 'submitted' WHERE id = r.id;
    UPDATE efile_filings SET confirmation_number = s->>'submission_id' WHERE id = r.efile_filing_id;
  END LOOP;
  RETURN v_tx;
END $_$;

-- @seq 469
CREATE FUNCTION public.mef_record_transmission_failure(p_return_ids uuid[], p_error text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v int;
BEGIN
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Worker only'; END IF;
  UPDATE mef_returns SET status = 'queued', warnings = array_append(warnings, 'Transmission failed: ' || coalesce(p_error,'')) WHERE id = ANY (p_return_ids) AND status = 'transmitting';
  GET DIAGNOSTICS v = ROW_COUNT; RETURN v;
END $$;

-- @seq 470
CREATE FUNCTION public.mef_set_efw(p_return_id uuid, p_amount numeric, p_settlement_date date, p_routing text, p_account text, p_account_type text DEFAULT 'checking'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE r mef_returns%ROWTYPE;
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  PERFORM platform__assert_tenant_admin(r.tenant_id);
  IF p_amount IS NULL THEN UPDATE mef_returns SET efw = NULL WHERE id = r.id; RETURN; END IF;
  IF r.balance_due <= 0 THEN RAISE EXCEPTION 'There is no balance due to pay'; END IF;
  IF p_amount <= 0 OR p_amount > 2 * r.balance_due THEN RAISE EXCEPTION 'The withdrawal must be more than 0 and no more than 200%% of the balance due (Pub 4163)'; END IF;
  IF p_settlement_date IS NULL OR p_settlement_date < current_date THEN RAISE EXCEPTION 'The withdrawal date cannot be in the past'; END IF;
  IF NOT mef__aba_ok(p_routing) THEN RAISE EXCEPTION 'That routing number is not valid'; END IF;
  IF p_account !~ '^[0-9A-Za-z-]{4,17}$' THEN RAISE EXCEPTION 'The account number must be 4 to 17 characters'; END IF;
  IF p_account_type NOT IN ('checking','savings') THEN RAISE EXCEPTION 'Account type is checking or savings'; END IF;
  UPDATE mef_returns SET efw = jsonb_build_object('amount', round(p_amount,2), 'settlement_date', p_settlement_date, 'account_type', p_account_type,
           'routing_last4', right(p_routing,4), 'account_last4', right(p_account,4), 'routing_sha256', tax__sha(p_routing), 'account_sha256', tax__sha(p_account),
           'account_secret_id', platform__vault_store('mef_efw_account', p_routing || ':' || p_account, 'EFW account for return ' || r.id))
   WHERE id = r.id;
END $_$;

-- @seq 471
CREATE FUNCTION public.mef_set_environment(p_return_id uuid, p_environment text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE;
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  IF auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Only the platform switches a return between ATS and production'; END IF;
  IF r.status IN ('queued','transmitting','submitted','accepted') THEN RAISE EXCEPTION 'Return is %', r.status; END IF;
  UPDATE mef_returns SET environment = p_environment WHERE id = r.id;
  UPDATE efile_filings SET environment = p_environment WHERE id = r.efile_filing_id;
END $$;

-- @seq 472
CREATE FUNCTION public.mef_sign_return(p_presentation_id uuid, p_content_sha256 text, p_method text, p_typed_name text, p_confirmed_amount numeric, p_taxpayer_pin text DEFAULT NULL::text, p_online_pin text DEFAULT NULL::text, p_efw_confirmed_amount numeric DEFAULT NULL::numeric, p_efw_consent boolean DEFAULT false, p_scanned_pdf_path text DEFAULT NULL::text, p_scanned_pdf_sha256 text DEFAULT NULL::text, p_client_ip inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE p tax_screen_presentations%ROWTYPE; r mef_returns%ROWTYPE; f mef_form_families%ROWTYPE; s mef_signers%ROWTYPE;
  v_dwell int; v_allowed text[]; v_id uuid; v_tp_pin uuid; v_ol_pin uuid; v_efw_doc uuid; v_n int; v_headline numeric;
BEGIN
  SELECT * INTO p FROM tax_screen_presentations WHERE id = p_presentation_id FOR UPDATE;
  IF NOT FOUND OR p.kind <> 'return_signature' THEN RAISE EXCEPTION 'Unknown signing screen'; END IF;
  PERFORM acct_assert_access(p.tenant_id);
  IF p.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the person shown this return can sign it'; END IF;
  IF p.used_at IS NOT NULL THEN RAISE EXCEPTION 'This signing screen was already used'; END IF;
  IF p.expires_at < now() THEN RAISE EXCEPTION 'This signing screen expired or the return changed; open it again'; END IF;
  IF p_content_sha256 IS DISTINCT FROM p.content_sha256 THEN RAISE EXCEPTION 'What you saw does not match this return; reload it'; END IF;
  v_dwell := (extract(epoch FROM (now() - p.presented_at)) * 1000)::int;
  IF v_dwell < tax__min_dwell_ms() THEN RAISE EXCEPTION 'Signed % ms after the return appeared; the signer must have time to review it', v_dwell; END IF;
  SELECT * INTO r FROM mef_returns WHERE id = p.return_id FOR UPDATE;
  IF r.version <> p.return_version THEN RAISE EXCEPTION 'The return changed after it was shown to you; review it again'; END IF;
  IF r.status NOT IN ('draft','awaiting_signature','rejected') THEN RAISE EXCEPTION 'This return is % and cannot be signed', r.status; END IF;
  IF cardinality(r.blocking_issues) > 0 THEN RAISE EXCEPTION 'Fix these first: %', array_to_string(r.blocking_issues, '; '); END IF;
  SELECT * INTO f FROM mef_form_families WHERE code = r.form_family;
  v_allowed := CASE WHEN r.ero_involved THEN f.methods_with_ero ELSE f.methods_online END;
  IF NOT p_method = ANY (v_allowed) THEN RAISE EXCEPTION 'Signature method % is not allowed here (allowed: %)', p_method, array_to_string(v_allowed, ', '); END IF;
  IF p_method <> 'not_required' THEN
    IF (f.jurat_documents->>p_method) IS NOT NULL AND p.document_id IS DISTINCT FROM
       (SELECT id FROM tax_disclosure_documents WHERE code = f.jurat_documents->>p_method AND status = 'published' ORDER BY version DESC LIMIT 1) THEN
      RAISE EXCEPTION 'The screen you saw was for a different signature method; open the signing screen for %', p_method;
    END IF;
    SELECT * INTO s FROM mef_signers WHERE entity_id = r.entity_id AND user_id = auth.uid() AND is_authorized_signer;
    IF NOT FOUND THEN RAISE EXCEPTION 'You are not an authorized signer for this business'; END IF;
    IF tax__norm_name(p_typed_name) <> tax__norm_name(s.legal_name) THEN RAISE EXCEPTION 'Type your legal name exactly as it appears on the signer record'; END IF;
  END IF;
  v_headline := (r.summary->>'headline_amount')::numeric;
  IF p_confirmed_amount IS NULL OR round(p_confirmed_amount, 2) <> round(v_headline, 2) THEN
    RAISE EXCEPTION 'The amount you typed does not match the % on this return. Review the return and type the amount shown.', lower(r.summary->>'headline_label');
  END IF;

  IF p_method = 'practitioner_pin' THEN
    IF p_taxpayer_pin IS NULL OR p_taxpayer_pin !~ '^[0-9]{5}$' OR p_taxpayer_pin = '00000' THEN
      RAISE EXCEPTION 'The signature PIN is any 5 digits except all zeros (Form 8879-EMP)';
    END IF;
    v_tp_pin := platform__vault_store('mef_taxpayer_pin', p_taxpayer_pin, 'Taxpayer PIN, return ' || r.id);
  ELSIF p_method = 'online_signature_pin' THEN
    IF r.ero_involved THEN RAISE EXCEPTION 'An Online Signature PIN cannot be used when a tax professional files the return'; END IF;
    IF s.role NOT IN ('owner','principal') THEN RAISE EXCEPTION 'Only an owner or principal can sign with an Online Signature PIN (Pub 4163 3.6.5)'; END IF;
    IF s.online_pin_status <> 'active' THEN RAISE EXCEPTION 'No active Online Signature PIN; register at least 45 days before the due date'; END IF;
    IF p_online_pin IS NULL OR p_online_pin !~ '^[0-9]{10}$' THEN RAISE EXCEPTION 'The Online Signature PIN is 10 digits'; END IF;
    SELECT count(DISTINCT sg.return_id) INTO v_n FROM mef_signatures sg JOIN mef_returns rr ON rr.id = sg.return_id
     WHERE sg.method = 'online_signature_pin' AND rr.entity_id = r.entity_id AND rr.tax_year = r.tax_year AND rr.id <> r.id
       AND rr.status IN ('signed','queued','transmitting','submitted','accepted');
    IF v_n >= 5 THEN RAISE EXCEPTION 'An Online Signature PIN signs at most 5 returns a year (Pub 4163 3.6.5); use the scanned Form 8453-EMP'; END IF;
    v_ol_pin := platform__vault_store('mef_online_pin_entry', p_online_pin, 'Online Signature PIN entry, return ' || r.id);
  ELSIF p_method = 'scanned_8453' THEN
    IF NOT mef__pdf_name_ok(regexp_replace(coalesce(p_scanned_pdf_path,''), '^.*/', '')) THEN
      RAISE EXCEPTION 'Attach the signed Form % as a PDF (letters, digits, space . _ - only; 64 characters max)', coalesce(f.signature_forms->>p_method, '8453');
    END IF;
    IF p_scanned_pdf_sha256 IS NULL OR p_scanned_pdf_sha256 !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'The scanned form hash is missing'; END IF;
  ELSIF p_method = 'reporting_agent_pin' THEN
    IF s.role <> 'reporting_agent' THEN RAISE EXCEPTION 'Only the reporting agent signs with the reporting agent PIN'; END IF;
    IF NOT EXISTS (SELECT 1 FROM mef_reporting_agent_auth a WHERE a.entity_id = r.entity_id AND a.revoked_at IS NULL
                     AND a.effective_from <= r.period_end AND r.form_code = ANY (a.forms)) THEN
      RAISE EXCEPTION 'No Form 8655 on file authorizing the reporting agent for %', r.form_code;
    END IF;
  ELSIF p_method = 'not_required' THEN
    IF r.balance_due > 0 OR r.efw IS NOT NULL THEN RAISE EXCEPTION 'A signature is required when a payment is made'; END IF;
  ELSIF p_method = 'ach_debit_indicator' THEN
    IF r.efw IS NULL THEN RAISE EXCEPTION 'The ACH debit indicator is only for a return paid by electronic funds withdrawal'; END IF;
  END IF;

  IF r.efw IS NOT NULL THEN
    IF NOT coalesce(p_efw_consent, false) THEN RAISE EXCEPTION 'Agree to the electronic funds withdrawal or remove the payment from the return'; END IF;
    IF p_efw_confirmed_amount IS NULL OR round(p_efw_confirmed_amount,2) <> round((r.efw->>'amount')::numeric,2) THEN
      RAISE EXCEPTION 'The withdrawal amount you typed does not match the payment on this return';
    END IF;
    IF (r.efw->>'settlement_date')::date < current_date THEN RAISE EXCEPTION 'The withdrawal date has passed; choose a new date'; END IF;
    IF (r.efw->>'amount')::numeric > 2 * r.balance_due THEN RAISE EXCEPTION 'The withdrawal is more than 200%% of the balance due'; END IF;
    SELECT id INTO v_efw_doc FROM tax_disclosure_documents WHERE code = 'efw_authorization' AND status = 'published' ORDER BY version DESC LIMIT 1;
  END IF;

  UPDATE mef_signatures SET status = 'superseded', voided_at = now() WHERE return_id = r.id AND status = 'valid';
  INSERT INTO mef_signatures(tenant_id, return_id, return_version, return_sha256, presentation_id, method, irs_form, signer_id, signer_user_id,
      signer_name, signer_title, pin_entered_by, taxpayer_pin_secret_id, online_pin_secret_id, confirmed_amount, jurat_document_id, efw_document_id,
      efw_amount, efw_settlement_date, scanned_pdf_path, scanned_pdf_sha256, dwell_ms, client_ip, user_agent)
  VALUES (r.tenant_id, r.id, r.version, r.return_sha256, p.id, p_method, f.signature_forms->>p_method, s.id, auth.uid(),
      coalesce(trim(p_typed_name), '(no signature required)'), s.title, CASE WHEN p_method IN ('practitioner_pin','online_signature_pin') THEN 'taxpayer' END,
      v_tp_pin, v_ol_pin, round(p_confirmed_amount,2), p.document_id, v_efw_doc,
      (r.efw->>'amount')::numeric, (r.efw->>'settlement_date')::date, p_scanned_pdf_path, p_scanned_pdf_sha256, v_dwell, p_client_ip, p_user_agent)
  RETURNING id INTO v_id;
  UPDATE tax_screen_presentations SET used_at = now() WHERE id = p.id;
  UPDATE mef_returns SET status = 'signed' WHERE id = r.id;
  RETURN v_id;
END $_$;

-- @seq 473
CREATE FUNCTION public.mef_signature_screen(p_return_id uuid, p_method text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE; f mef_form_families%ROWTYPE; s mef_signers%ROWTYPE; j tax_disclosure_documents%ROWTYPE; e tax_disclosure_documents%ROWTYPE;
  v_allowed text[]; v_body text; v_hash text; v_pid uuid; v_entity_name text;
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.status NOT IN ('draft','awaiting_signature','rejected') THEN RAISE EXCEPTION 'This return is % and is not waiting for a signature', r.status; END IF;
  IF cardinality(r.blocking_issues) > 0 THEN RAISE EXCEPTION 'Fix these first: %', array_to_string(r.blocking_issues, '; '); END IF;
  SELECT * INTO f FROM mef_form_families WHERE code = r.form_family;
  v_allowed := CASE WHEN r.ero_involved THEN f.methods_with_ero ELSE f.methods_online END;
  IF NOT p_method = ANY (v_allowed) THEN
    RAISE EXCEPTION 'Signature method % is not allowed for % % (allowed: %)', p_method, r.form_code,
      CASE WHEN r.ero_involved THEN 'with an ERO' ELSE 'filed directly' END, array_to_string(v_allowed, ', ');
  END IF;
  SELECT * INTO s FROM mef_signers WHERE entity_id = r.entity_id AND user_id = auth.uid() AND is_authorized_signer;
  IF NOT FOUND AND p_method <> 'not_required' THEN RAISE EXCEPTION 'You are not an authorized signer for this business'; END IF;
  SELECT * INTO j FROM tax_disclosure_documents WHERE code = f.jurat_documents->>p_method AND status = 'published' ORDER BY version DESC LIMIT 1;
  IF r.efw IS NOT NULL THEN SELECT * INTO e FROM tax_disclosure_documents WHERE code = 'efw_authorization' AND status = 'published' ORDER BY version DESC LIMIT 1; END IF;
  SELECT coalesce(display_name, legal_name) INTO v_entity_name FROM acct_entities WHERE id = r.entity_id;
  v_body := concat_ws(E'\n\n', 'Form ' || r.form_code || ' - ' || r.period_label || ' - ' || v_entity_name,
                      (SELECT string_agg(coalesce(x->>'line','') || '  ' || (x->>'label') || ': ' || (x->>'amount'), E'\n')
                         FROM jsonb_array_elements(coalesce(r.summary->'part_i', '[]')) x),
                      (r.summary->>'headline_label') || ': ' || (r.summary->>'headline_amount'),
                      j.body_template,
                      CASE WHEN r.efw IS NOT NULL THEN e.body_template || E'\nWithdrawal: ' || (r.efw->>'amount') || ' on ' || (r.efw->>'settlement_date')
                             || ' from ' || (r.efw->>'account_type') || ' account ending ' || (r.efw->>'account_last4') END);
  v_hash := tax__sha(v_body || '|' || r.return_sha256);
  INSERT INTO tax_screen_presentations(tenant_id, user_id, kind, document_id, return_id, return_version, rendered_body, content_sha256)
  VALUES (r.tenant_id, auth.uid(), 'return_signature', j.id, r.id, r.version, v_body, v_hash) RETURNING id INTO v_pid;
  RETURN jsonb_build_object(
    'presentation_id', v_pid, 'content_sha256', v_hash, 'return_id', r.id, 'return_version', r.version, 'return_sha256', r.return_sha256,
    'form', r.form_code, 'period', r.period_label, 'entity', v_entity_name, 'part_i', coalesce(r.summary->'part_i','[]'),
    'headline_label', r.summary->>'headline_label', 'headline_amount', r.summary->'headline_amount',
    'warnings', to_jsonb(r.warnings),
    'method', p_method, 'irs_form', f.signature_forms->>p_method,
    'signer', CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('name', s.legal_name, 'title', s.title, 'role', s.role) END,
    'jurat', CASE WHEN j.id IS NULL THEN NULL ELSE jsonb_build_object('title', j.title, 'text', j.body_template) END,
    'efw', CASE WHEN r.efw IS NULL THEN NULL ELSE jsonb_build_object('text', e.body_template, 'amount', r.efw->'amount',
             'settlement_date', r.efw->'settlement_date', 'account_type', r.efw->'account_type', 'account_last4', r.efw->'account_last4',
             'cancel', 'Call the U.S. Treasury Financial Agent at 1-888-353-4537 no later than 2 business days before the payment date') END,
    'inputs', jsonb_build_object(
      'typed_name', p_method <> 'not_required', 'typed_amount', true,
      'taxpayer_pin', p_method = 'practitioner_pin', 'online_pin', p_method = 'online_signature_pin',
      'scanned_pdf', p_method = 'scanned_8453', 'efw_typed_amount', r.efw IS NOT NULL),
    'rules', jsonb_build_array('Show every Part I amount before the signature fields', 'The signer types the headline amount; it is not filled in',
      'The signer types their name; it is not filled in', 'Any change to the return after signing voids the signature'),
    'expires_at', (SELECT expires_at FROM tax_screen_presentations WHERE id = v_pid));
END $$;

-- @seq 474
CREATE FUNCTION public.mef_signer_set_online_pin(p_signer_id uuid, p_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE s mef_signers%ROWTYPE;
BEGIN
  SELECT * INTO s FROM mef_signers WHERE id = p_signer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown signer'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF s.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the PIN holder can enter their Online Signature PIN'; END IF;
  IF s.role NOT IN ('owner','principal') THEN RAISE EXCEPTION 'Online Signature PINs are only for owners and principals, not tax professionals (Pub 4163 3.6.5)'; END IF;
  IF p_pin !~ '^[0-9]{10}$' THEN RAISE EXCEPTION 'The Online Signature PIN is 10 digits'; END IF;
  UPDATE mef_signers SET online_pin_secret_id = platform__vault_store('mef_online_pin', p_pin, 'Online Signature PIN ' || s.id),
         online_pin_status = 'active', online_pin_registered_at = coalesce(online_pin_registered_at, now()), updated_at = now()
   WHERE id = s.id;
END $_$;

-- @seq 475
CREATE FUNCTION public.mef_signer_upsert(p_tenant_id uuid, p_user_id uuid, p_legal_name text, p_title text, p_role text, p_is_authorized boolean DEFAULT true, p_entity_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; v_entity uuid;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  IF NOT EXISTS (SELECT 1 FROM acct_entities WHERE id = v_entity AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Unknown entity'; END IF;
  IF NOT EXISTS (SELECT 1 FROM tenant_memberships tm WHERE tm.tenant_id = p_tenant_id AND tm.user_id = p_user_id AND tm.active AND tm.status = 'active') THEN RAISE EXCEPTION 'The signer must be a member of this business'; END IF;
  INSERT INTO mef_signers(tenant_id, entity_id, user_id, legal_name, title, role, is_authorized_signer, created_by)
  VALUES (p_tenant_id, v_entity, p_user_id, trim(p_legal_name), p_title, p_role, p_is_authorized, auth.uid())
  ON CONFLICT (entity_id, user_id) DO UPDATE SET legal_name = EXCLUDED.legal_name, title = EXCLUDED.title, role = EXCLUDED.role,
     is_authorized_signer = EXCLUDED.is_authorized_signer, updated_at = now(),
     online_pin_status = CASE WHEN EXCLUDED.role IN ('owner','principal') THEN mef_signers.online_pin_status ELSE 'revoked' END
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;

-- @seq 476
CREATE FUNCTION public.mef_update_return_data(p_return_id uuid, p_return_data jsonb, p_summary jsonb DEFAULT NULL::jsonb, p_balance_due numeric DEFAULT NULL::numeric, p_overpayment numeric DEFAULT NULL::numeric) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE; v int;
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  PERFORM platform__assert_tenant_admin(r.tenant_id);
  UPDATE mef_returns SET return_data = coalesce(p_return_data, return_data), summary = coalesce(p_summary, summary),
         balance_due = coalesce(p_balance_due, balance_due), overpayment = coalesce(p_overpayment, overpayment)
   WHERE id = r.id RETURNING version INTO v;
  RETURN v;
END $$;

-- @seq 477
CREATE FUNCTION public.mef_void_return(p_return_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r mef_returns%ROWTYPE;
BEGIN
  SELECT * INTO r FROM mef_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown return'; END IF;
  PERFORM platform__assert_tenant_admin(r.tenant_id);
  IF r.status IN ('transmitting','submitted','accepted') THEN RAISE EXCEPTION 'A % return cannot be voided', r.status; END IF;
  UPDATE mef_signatures SET status = 'revoked', voided_at = now() WHERE return_id = r.id AND status = 'valid';
  UPDATE mef_returns SET status = 'void', warnings = array_append(warnings, 'Voided: ' || coalesce(p_reason,'')) WHERE id = r.id;
END $$;

-- @seq 481
CREATE FUNCTION public.partnership18_calculate(p_start date, p_end date, p_periods jsonb, p_items jsonb, p_agreement_review_ref text, p_scope_reviewed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE per jsonb; item jsonb; owner jsonb; share_row jsonb; allocation jsonb;
 periods_count int; n int; previous_end date; d1 date; d2 date; amount numeric;
 shares jsonb; lines jsonb:='[]'; reconciliations jsonb:='[]'; issues jsonb:='[]';
 summaries jsonb; period_id text; category text; method text; distributed numeric;
 allowed text[]:=ARRAY['ordinary_business','rental_real_estate','other_rental','interest',
 'ordinary_dividends','qualified_dividends','royalties','short_term_capital','long_term_capital',
 'section1231','other_income','section179','charitable','other_deduction','tax_exempt_interest',
 'other_tax_exempt','nondeductible','credits','distributions_cash','distributions_property',
 'gp_services','gp_capital'];
BEGIN
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start OR p_end-p_start>370 THEN RAISE EXCEPTION 'Invalid partnership period';END IF;
 IF p_periods IS NULL OR jsonb_typeof(p_periods)<>'array' OR jsonb_array_length(p_periods)=0
 OR p_items IS NULL OR jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'Periods and items arrays required';END IF;
 IF coalesce(btrim(p_agreement_review_ref),'')='' THEN RAISE EXCEPTION 'Agreement review reference required';END IF;
 IF p_scope_reviewed IS DISTINCT FROM true THEN issues:=issues||jsonb_build_array('Partnership allocation scope review incomplete');END IF;
 periods_count:=jsonb_array_length(p_periods);
 IF (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(p_periods))<>periods_count THEN RAISE EXCEPTION 'Duplicate period IDs';END IF;
 previous_end:=p_start-1;
 FOR per IN SELECT value FROM jsonb_array_elements(p_periods) ORDER BY (value->>'start')::date LOOP
 IF coalesce(btrim(per->>'id'),'')='' THEN RAISE EXCEPTION 'Period ID missing';END IF;
 d1:=(per->>'start')::date;d2:=(per->>'end')::date;
 IF d1 IS NULL OR d2 IS NULL OR d1<>previous_end+1 OR d2<d1 OR d2>p_end THEN
 RAISE EXCEPTION 'Periods must cover year without gaps or overlaps';END IF;
 previous_end:=d2;
 IF jsonb_typeof(per->'partners') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Partners required';END IF;
 -- Validate both sets even when the year has no corresponding positive/negative item.
 SELECT jsonb_agg(jsonb_build_object('partner_id',value->>'partner_id','share',value->'profit'))
 INTO shares FROM jsonb_array_elements(per->'partners');
 PERFORM public.partnership18_split(0,shares);
 SELECT jsonb_agg(jsonb_build_object('partner_id',value->>'partner_id','share',value->'loss'))
 INTO shares FROM jsonb_array_elements(per->'partners');
 PERFORM public.partnership18_split(0,shares);
 END LOOP;
 IF previous_end<>p_end THEN RAISE EXCEPTION 'Periods do not cover end of tax year';END IF;
 n:=jsonb_array_length(p_items);
 IF (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(p_items))<>n THEN RAISE EXCEPTION 'Unique item IDs required';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
 IF coalesce(btrim(item->>'id'),'')='' OR coalesce(btrim(item->>'source_ref'),'')=''
 OR jsonb_typeof(item->'amount') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Item requires id, source_ref and numeric amount';END IF;
 amount:=(item->>'amount')::numeric;
 IF amount<>round(amount,2) THEN RAISE EXCEPTION 'Item amounts must be cents';END IF;
 category:=item->>'category';
 IF category IS NULL OR NOT category=ANY(allowed) THEN RAISE EXCEPTION 'Unsupported category %',category;END IF;
 SELECT value INTO per FROM jsonb_array_elements(p_periods) WHERE value->>'id'=item->>'period_id';
 IF per IS NULL THEN RAISE EXCEPTION 'Unknown period for item %',item->>'id';END IF;
 period_id:=per->>'id';
 IF coalesce((item->>'section704c')::boolean,false)
 OR coalesce((item->>'reverse704c')::boolean,false)
 OR coalesce((item->>'nonrecourse')::boolean,false)
 OR coalesce((item->>'special_basis_adjustment')::boolean,false) THEN
 issues:=issues||jsonb_build_array('Unimplemented special tax allocation: '||(item->>'id'));CONTINUE;END IF;
 IF category IN ('qualified_dividends','credits','distributions_property') THEN
 -- These require relationship/code/property details beyond a single dollar pool.
 issues:=issues||jsonb_build_array('Category needs supplemental coded/property allocation: '||(item->>'id'));CONTINUE;END IF;
 IF coalesce((item->>'extraordinary')::boolean,false) THEN
 IF NOT item ? 'shares' OR nullif(item->>'event_date','') IS NULL THEN
 issues:=issues||jsonb_build_array('Extraordinary item needs event-date ownership review: '||(item->>'id'));CONTINUE;END IF;
 IF (item->>'event_date')::date<(per->>'start')::date OR (item->>'event_date')::date>(per->>'end')::date THEN
 RAISE EXCEPTION 'Extraordinary event is outside item period';END IF;
 END IF;
 IF category IN ('gp_services','gp_capital','distributions_cash') THEN
 IF amount<0 OR coalesce(item->>'recipient','')='' THEN RAISE EXCEPTION 'Direct item requires recipient and nonnegative amount';END IF;
 IF item ? 'shares' THEN RAISE EXCEPTION 'Direct item cannot also supply shares';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(per->'partners') o WHERE o->>'partner_id'=item->>'recipient') THEN
 RAISE EXCEPTION 'Direct recipient is not a period partner';END IF;
 shares:=jsonb_build_array(jsonb_build_object('partner_id',item->>'recipient','share',1));method:='direct';
 ELSE
 IF item ? 'shares' THEN
 IF coalesce(btrim(item->>'agreement_ref'),'')='' OR coalesce(btrim(item->>'review_ref'),'')='' THEN
 RAISE EXCEPTION 'Special shares require agreement_ref and review_ref';END IF;
 shares:=item->'shares';method:='reviewed_special_ratio';
 IF jsonb_typeof(shares) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Shares array required';END IF;
 FOR share_row IN SELECT value FROM jsonb_array_elements(shares) LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(per->'partners') o WHERE o->>'partner_id'=share_row->>'partner_id') THEN
 RAISE EXCEPTION 'Special allocation includes nonmember';END IF;
 END LOOP;
 ELSE
 SELECT jsonb_agg(jsonb_build_object('partner_id',o->>'partner_id',
 'share',CASE WHEN amount<0 THEN o->'loss' ELSE o->'profit' END)) INTO shares
 FROM jsonb_array_elements(per->'partners') o;
 method:=CASE WHEN amount<0 THEN 'period_loss_ratio' ELSE 'period_profit_ratio' END;
 END IF;
 END IF;
 allocation:=public.partnership18_split(amount,shares);
 SELECT coalesce(sum((value->>'amount')::numeric),0) INTO distributed FROM jsonb_array_elements(allocation);
 IF distributed<>amount THEN RAISE EXCEPTION 'Allocation reconciliation failure';END IF;
 FOR owner IN SELECT value FROM jsonb_array_elements(allocation) LOOP
 lines:=lines||jsonb_build_array(owner||jsonb_build_object('item_id',item->>'id','period_id',period_id,
 'category',category,'source_ref',item->>'source_ref','method',method,
 'agreement_ref',coalesce(item->>'agreement_ref',p_agreement_review_ref),'review_ref',item->>'review_ref'));
 END LOOP;
 reconciliations:=reconciliations||jsonb_build_array(jsonb_build_object('item_id',item->>'id',
 'input_amount',amount,'allocated_amount',distributed,'difference',amount-distributed));
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('partner_id',pid,'category',cat,'amount',amt) ORDER BY pid,cat),'[]')
 INTO summaries FROM(SELECT value->>'partner_id' pid,value->>'category' cat,
 sum((value->>'amount')::numeric) amt FROM jsonb_array_elements(lines) GROUP BY 1,2) q;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(issues)=0 THEN 'allocated_workpaper' ELSE 'blocked' END,
 'period_start',p_start,'period_end',p_end,'allocation_lines',lines,'partner_category_totals',summaries,
 'item_reconciliation',reconciliations,'blocking_issues',issues,'filing_ready',false,
 'method','supplied closing-of-books period amounts with reviewed allocation ratios',
 'guaranteed_payment_expense','must already be correctly reflected upstream; not deducted here',
 'limitations','No automatic 704(b) validity determination, 704(c), owner loss limits, liabilities, or complete K-1');
END $$;

-- @seq 482
CREATE FUNCTION public.partnership18_save(p_tenant uuid, p_entity uuid, p_start date, p_end date, p_periods jsonb, p_items jsonb, p_agreement_review_ref text, p_scope_reviewed boolean DEFAULT false, p_source_calculation_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'partnership18'
    AS $$
DECLARE inp jsonb;res jsonb;rid uuid;
BEGIN
 PERFORM public.acct_assert_access(p_tenant);
 IF NOT EXISTS(SELECT 1 FROM public.acct_entities WHERE id=p_entity AND tenant_id=p_tenant) THEN RAISE EXCEPTION 'Entity mismatch';END IF;
 inp:=jsonb_build_object('start',p_start,'end',p_end,'periods',p_periods,'items',p_items,
 'agreement_review_ref',p_agreement_review_ref,'scope_reviewed',p_scope_reviewed,
 'source_calculation_id',p_source_calculation_id);
 res:=public.partnership18_calculate(p_start,p_end,p_periods,p_items,p_agreement_review_ref,p_scope_reviewed);
 INSERT INTO partnership18.runs(tenant_id,entity_id,source_calculation_id,input_sha256,input,result,created_by)
 VALUES(p_tenant,p_entity,p_source_calculation_id,encode(sha256(convert_to(inp::text,'UTF8')),'hex'),inp,res,auth.uid()) RETURNING id INTO rid;
 RETURN res||jsonb_build_object('allocation_run_id',rid);
END $$;

-- @seq 483
CREATE FUNCTION public.partnership18_split(p_amount numeric, p_shares jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE x jsonb; total numeric:=0; cnt int; cents numeric; outp jsonb;
BEGIN
 IF p_amount IS NULL OR p_amount<>round(p_amount,2) OR p_amount::text IN ('NaN','Infinity','-Infinity')
 OR p_shares IS NULL OR jsonb_typeof(p_shares)<>'array' THEN RAISE EXCEPTION 'Finite cent amount and shares array required'; END IF;
 cnt:=jsonb_array_length(p_shares);
 IF cnt=0 THEN RAISE EXCEPTION 'Empty shares'; END IF;
 IF (SELECT count(DISTINCT value->>'partner_id') FROM jsonb_array_elements(p_shares))<>cnt THEN
 RAISE EXCEPTION 'Unique partner IDs required'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_shares) LOOP
 IF coalesce(btrim(x->>'partner_id'),'')='' OR jsonb_typeof(x->'share') IS DISTINCT FROM 'number'
 OR (x->>'share')::numeric<0 OR (x->>'share')::numeric>1 THEN RAISE EXCEPTION 'Invalid share';END IF;
 total:=total+(x->>'share')::numeric;
 END LOOP;
 IF total<>1 THEN RAISE EXCEPTION 'Shares must sum exactly to one, got %',total; END IF;
 cents:=abs(p_amount)*100;
 WITH raw AS (
 SELECT value->>'partner_id' pid,(value->>'share')::numeric share,
 cents*(value->>'share')::numeric exact FROM jsonb_array_elements(p_shares)),
 floored AS (SELECT *,floor(exact) base,exact-floor(exact) fraction FROM raw),
 ranked AS (SELECT *,row_number() OVER(ORDER BY fraction DESC,pid) rank,
 cents-sum(base) OVER() residual FROM floored)
 SELECT jsonb_agg(jsonb_build_object('partner_id',pid,'share',share,
 'amount',sign(p_amount)*(base+CASE WHEN rank<=residual THEN 1 ELSE 0 END)/100) ORDER BY pid)
 INTO outp FROM ranked;
 RETURN outp;
END $$;

-- @seq 560
CREATE FUNCTION public.tax16_claim_job() RETURNS SETOF tax16.jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
BEGIN
 PERFORM tax16.assert_worker();
 UPDATE tax16.jobs SET status='failed',last_error='Lease expired at retry limit'
 WHERE status='running' AND lease_until<now() AND attempts>=max_attempts;
 RETURN QUERY WITH candidate AS (
 SELECT id FROM tax16.jobs WHERE attempts<max_attempts AND
 ((status IN ('pending','failed') AND available_at<=now()) OR
 (status='running' AND lease_until<now()))
 ORDER BY available_at,id FOR UPDATE SKIP LOCKED LIMIT 1)
 UPDATE tax16.jobs j SET status='running',attempts=j.attempts+1,
 lease_until=now()+interval '5 minutes',lease_token=gen_random_uuid()
 FROM candidate c WHERE j.id=c.id RETURNING j.*;
END $$;

-- @seq 561
CREATE FUNCTION public.tax16_configure(p_transmission boolean, p_fee_enabled boolean, p_fee numeric, p_effective_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE old_row jsonb; new_row jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.platform_is_admin(),false) THEN
  RAISE EXCEPTION 'Global platform admin required' USING ERRCODE='42501';
 END IF;
 SELECT to_jsonb(s) INTO old_row FROM tax16.settings s WHERE singleton FOR UPDATE;
 UPDATE tax16.settings SET transmission_enabled=p_transmission,
 filing_fee_enabled=p_fee_enabled, filing_fee_amount=p_fee,
 fee_effective_at=p_effective_at,updated_at=now(),updated_by=auth.uid() WHERE singleton;
 SELECT to_jsonb(s) INTO new_row FROM tax16.settings s WHERE singleton;
 INSERT INTO tax16.admin_audit(actor,action,old_value,new_value)
 VALUES(auth.uid(),'settings',old_row,new_row);
END $$;

-- @seq 562
CREATE FUNCTION public.tax16_finish_job(p_job uuid, p_lease uuid, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
BEGIN
 PERFORM tax16.assert_worker();
 UPDATE tax16.jobs SET status=CASE WHEN p_error IS NULL THEN 'completed' ELSE 'failed' END,
 completed_at=CASE WHEN p_error IS NULL THEN now() END,last_error=left(p_error,2000),
 available_at=now()+interval '1 minute'*least(attempts*attempts,60),lease_until=NULL,lease_token=NULL
 WHERE id=p_job AND status='running' AND lease_token=p_lease AND lease_until>now();
 IF NOT FOUND THEN RAISE EXCEPTION 'Expired or incorrect worker lease'; END IF;
END $$;

-- @seq 563
CREATE FUNCTION public.tax16_request_preview(p_return uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE r public.mef_returns%ROWTYPE; v uuid; k text;
BEGIN
 SELECT * INTO r FROM public.mef_returns WHERE id=p_return FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Return not found'; END IF;
 PERFORM public.acct_assert_access(r.tenant_id);
 IF r.status='void' THEN RAISE EXCEPTION 'Return voided'; END IF;
 k:='preview:'||r.id||':'||r.version;
 INSERT INTO tax16.jobs(tenant_id,return_id,return_version,kind,idempotency_key,payload)
 VALUES(r.tenant_id,r.id,r.version,'render_preview',k,
 jsonb_build_object('return_data',r.return_data,'summary',r.summary,'return_sha256',r.return_sha256))
 ON CONFLICT(idempotency_key) DO NOTHING RETURNING id INTO v;
 IF v IS NULL THEN SELECT id INTO v FROM tax16.jobs WHERE idempotency_key=k; END IF;
 RETURN v;
END $$;

-- @seq 564
CREATE FUNCTION public.tax16_teller_bind_verified(p_challenge uuid, p_enrollment uuid, p_connection uuid, p_secret uuid, p_token_sha256 text, p_signature_sha256 text, p_verifier_version text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE c tax16.teller_challenges%ROWTYPE; e public.teller_enrollments%ROWTYPE;
 x public.integration_connections%ROWTYPE; v uuid;
BEGIN
 PERFORM tax16.assert_worker();
 SELECT * INTO c FROM tax16.teller_challenges WHERE id=p_challenge FOR UPDATE;
 IF NOT FOUND OR c.consumed_at IS NOT NULL OR c.expires_at<=now() THEN
  RAISE EXCEPTION 'Invalid, expired or consumed Teller challenge'; END IF;
 SELECT * INTO e FROM public.teller_enrollments WHERE id=p_enrollment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Enrollment missing'; END IF;
 SELECT * INTO x FROM public.integration_connections WHERE id=p_connection FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Connection missing'; END IF;
 IF e.tenant_id<>c.tenant_id OR x.tenant_id<>c.tenant_id OR e.connection_id<>x.id
 OR x.provider_code<>'teller' OR e.environment<>c.environment
 OR x.environment<>c.environment OR x.connected_by IS DISTINCT FROM c.user_id THEN
  RAISE EXCEPTION 'Teller challenge/enrollment/connection mismatch'; END IF;
 IF p_secret IS NULL THEN RAISE EXCEPTION 'Vault token reference required'; END IF;
 -- Worker must verify the secret exists and matches p_token_sha256 before this RPC.
 INSERT INTO tax16.teller_verifications(tenant_id,challenge_id,enrollment_id,connection_id,
 token_sha256,signature_sha256,verifier_version)
 VALUES(c.tenant_id,c.id,e.id,x.id,p_token_sha256,p_signature_sha256,p_verifier_version)
 RETURNING id INTO v;
 UPDATE public.teller_enrollments SET access_token_secret_id=p_secret,
 connect_signature_verified=true WHERE id=e.id;
 UPDATE public.integration_connections SET credential_secret_id=p_secret,
 updated_at=now() WHERE id=x.id;
 UPDATE tax16.teller_challenges SET consumed_at=now() WHERE id=c.id;
 RETURN v;
END $$;

-- @seq 565
CREATE FUNCTION public.tax16_teller_challenge(p_tenant uuid, p_environment text, p_nonce_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE v uuid;
BEGIN
 PERFORM public.acct_assert_access(p_tenant);
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'User required'; END IF;
 INSERT INTO tax16.teller_challenges(tenant_id,user_id,environment,nonce_sha256)
 VALUES(p_tenant,auth.uid(),p_environment,p_nonce_sha256) RETURNING id INTO v;
 RETURN v;
END $$;

-- @seq 566
CREATE FUNCTION public.tax__consent_immutable_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Signed consents cannot be deleted; revoke them'; END IF;
  IF (to_jsonb(NEW) - ARRAY['status','revoked_at','revoked_by','revoke_reason','copy_email_id','copy_error'])
     IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','revoked_at','revoked_by','revoke_reason','copy_email_id','copy_error']) THEN
    RAISE EXCEPTION 'A signed consent cannot be altered (Rev. Proc. 2013-14 sec. 5.04(4))';
  END IF;
  IF OLD.status = 'revoked' AND NEW.status <> 'revoked' THEN RAISE EXCEPTION 'A revoked consent cannot be reinstated; sign a new one'; END IF;
  RETURN NEW;
END $$;

-- @seq 567
CREATE FUNCTION public.tax__consent_item_immutable_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Consent selections cannot be changed after signing'; END $$;

-- @seq 568
CREATE FUNCTION public.tax__doc_immutable_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.body_sha256 := encode(sha256(convert_to(NEW.body_template, 'UTF8')), 'hex');
  IF TG_OP = 'UPDATE' AND OLD.status IN ('published','retired') AND
     (NEW.body_template IS DISTINCT FROM OLD.body_template OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.title IS DISTINCT FROM OLD.title) THEN
    RAISE EXCEPTION 'Published document %.v% cannot change; publish version %', OLD.code, OLD.version, OLD.version + 1;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'retired' AND NEW.status <> 'retired' THEN RAISE EXCEPTION 'Retired documents stay retired'; END IF;
  RETURN NEW;
END $$;

-- @seq 569
CREATE FUNCTION public.tax__min_dwell_ms() RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT 3000;  -- fixed on purpose: not overridable from a client session
$$;

-- @seq 570
CREATE FUNCTION public.tax__norm_name(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT lower(regexp_replace(trim(coalesce(p,'')), '\s+', ' ', 'g'));
$$;

-- @seq 571
CREATE FUNCTION public.tax__render(p_template text, p_tenant_id uuid, p_entity_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT replace(replace(replace(p_template,
           '{{preparer_name}}', coalesce((SELECT ero_firm_name FROM mef_providers WHERE tenant_id IS NULL ORDER BY created_at LIMIT 1), 'Unsaid')),
           '{{taxpayer_name}}', coalesce((SELECT legal_name FROM acct_entities WHERE id = p_entity_id), '')),
           '{{entity_name}}', coalesce((SELECT coalesce(display_name, legal_name) FROM acct_entities WHERE id = p_entity_id), ''));
$$;

-- @seq 572
CREATE FUNCTION public.tax__sha(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT encode(sha256(convert_to(coalesce(p,''), 'UTF8')), 'hex');
$$;

-- @seq 573
CREATE FUNCTION public.tax_consent_copy(p_consent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c tax_consents%ROWTYPE;
BEGIN
  SELECT * INTO c FROM tax_consents WHERE id = p_consent_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown consent'; END IF;
  PERFORM acct_assert_access(c.tenant_id);
  RETURN jsonb_build_object('title', (SELECT title FROM tax_disclosure_documents WHERE id = c.document_id), 'body', c.rendered_body,
    'selections', (SELECT jsonb_agg(jsonb_build_object('item', i.label, 'granted', ci.granted) ORDER BY i.sort_order)
                     FROM tax_consent_items ci JOIN tax_disclosure_items i ON i.id = ci.item_id WHERE ci.consent_id = c.id),
    'signed_by', c.signer_name, 'signed_on', c.signed_on, 'expires_on', c.expires_on, 'status', c.status, 'revoked_at', c.revoked_at,
    'content_sha256', c.content_sha256);
END $$;

-- @seq 574
CREATE FUNCTION public.tax_consent_is_active(p_tenant_id uuid, p_document_code text, p_item_code text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT (platform_is_tenant_member(p_tenant_id) OR auth.role() = 'service_role') THEN RETURN false; END IF;
  RETURN EXISTS (
    SELECT 1 FROM tax_consents c JOIN tax_disclosure_documents d ON d.id = c.document_id
      JOIN tax_consent_items ci ON ci.consent_id = c.id AND ci.granted JOIN tax_disclosure_items i ON i.id = ci.item_id
     WHERE c.tenant_id = p_tenant_id AND d.code = p_document_code AND i.item_code = p_item_code
       AND c.status = 'active' AND (c.expires_on IS NULL OR c.expires_on >= current_date));
END $$;

-- @seq 575
CREATE FUNCTION public.tax_consent_revoke(p_consent_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c tax_consents%ROWTYPE;
BEGIN
  SELECT * INTO c FROM tax_consents WHERE id = p_consent_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown consent'; END IF;
  IF NOT (c.signer_user_id = auth.uid() OR platform_is_tenant_admin(c.tenant_id) OR auth.role() = 'service_role') THEN
    RAISE EXCEPTION 'Only the signer or an owner can revoke this consent';
  END IF;
  IF c.status = 'revoked' THEN RETURN; END IF;
  UPDATE tax_consents SET status = 'revoked', revoked_at = now(), revoked_by = auth.uid(), revoke_reason = p_reason WHERE id = c.id;
END $$;

-- @seq 576
CREATE FUNCTION public.tax_consent_screen(p_tenant_id uuid, p_document_code text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d tax_disclosure_documents%ROWTYPE; v_entity uuid; v_body text; v_items jsonb; v_hash text; v_pid uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to view this consent'; END IF;
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  IF NOT EXISTS (SELECT 1 FROM acct_entities WHERE id = v_entity AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Unknown entity'; END IF;
  SELECT * INTO d FROM tax_disclosure_documents WHERE code = p_document_code AND status = 'published' ORDER BY version DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No published document %', p_document_code; END IF;
  IF d.kind NOT IN ('consent_use','consent_disclose') THEN RAISE EXCEPTION '% is not a consent; it is shown on the signing screen', p_document_code; END IF;
  v_body := tax__render(d.body_template, p_tenant_id, v_entity);
  SELECT coalesce(jsonb_agg(jsonb_build_object('item_code', i.item_code, 'label', i.label, 'purpose', i.purpose,
           'recipient', tax__render(i.recipient, p_tenant_id, v_entity), 'recipient_location', i.recipient_location,
           'data_described', i.data_described, 'entire_return', i.entire_return, 'includes_ssn', i.includes_ssn,
           'selected', false) ORDER BY i.sort_order), '[]'::jsonb)
    INTO v_items FROM tax_disclosure_items i WHERE i.document_id = d.id;
  v_hash := tax__sha(v_body || '|' || v_items::text);
  INSERT INTO tax_screen_presentations(tenant_id, user_id, kind, document_id, rendered_body, content_sha256)
  VALUES (p_tenant_id, auth.uid(), 'consent', d.id, v_body || E'\n\n' || v_items::text, v_hash) RETURNING id INTO v_pid;
  RETURN jsonb_build_object(
    'presentation_id', v_pid, 'content_sha256', v_hash, 'document_code', d.code, 'version', d.version, 'kind', d.kind,
    'title', d.title, 'body', v_body, 'items', v_items, 'requires_items', d.requires_items,
    'default_duration', CASE WHEN d.default_duration_days IS NULL THEN NULL ELSE 'one year from the date of signature unless you choose another period' END,
    'signature', jsonb_build_object('method', 'typed_name', 'prompt', 'Type your full name to sign', 'prefill', false, 'date', current_date),
    'render_rules', jsonb_build_array(
      'Show this consent on its own screen; only consent text and navigation controls (Rev. Proc. 2013-14 sec. 5.03)',
      'Text at least the size of the app''s normal body text, with sufficient contrast',
      'Every choice starts unselected; the taxpayer must select each one (sec. 5.04(2), 5.05)',
      'Never pre-fill the name field (sec. 6.02(b))',
      'Offer Print / Save as PDF before and after signing',
      'Declining is always available and never blocks preparing or filing the return'),
    'expires_at', (SELECT expires_at FROM tax_screen_presentations WHERE id = v_pid));
END $$;

-- @seq 577
CREATE FUNCTION public.tax_consent_sign(p_presentation_id uuid, p_content_sha256 text, p_selected_items text[], p_typed_name text, p_signer_title text DEFAULT NULL::text, p_duration_days integer DEFAULT NULL::integer, p_client_ip inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p tax_screen_presentations%ROWTYPE; d tax_disclosure_documents%ROWTYPE; v_id uuid; v_dwell int; v_bad text[];
  v_entity uuid; v_email text; v_mail uuid;
BEGIN
  SELECT * INTO p FROM tax_screen_presentations WHERE id = p_presentation_id FOR UPDATE;
  IF NOT FOUND OR p.kind <> 'consent' THEN RAISE EXCEPTION 'Unknown consent screen'; END IF;
  PERFORM acct_assert_access(p.tenant_id);
  IF p.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'This consent was shown to a different user; only the person who saw it can sign it'; END IF;
  IF p.used_at IS NOT NULL THEN RAISE EXCEPTION 'This consent screen was already used; open it again'; END IF;
  IF p.expires_at < now() THEN RAISE EXCEPTION 'This consent screen expired; open it again'; END IF;
  IF p_content_sha256 IS DISTINCT FROM p.content_sha256 THEN RAISE EXCEPTION 'The text you saw does not match the current consent; reload it'; END IF;
  SELECT * INTO d FROM tax_disclosure_documents WHERE id = p.document_id;
  IF d.status <> 'published' THEN RAISE EXCEPTION 'This consent version is no longer offered'; END IF;
  v_dwell := (extract(epoch FROM (now() - p.presented_at)) * 1000)::int;
  IF v_dwell < tax__min_dwell_ms() THEN RAISE EXCEPTION 'Signed % ms after the consent appeared; the taxpayer must have time to read it', v_dwell; END IF;
  IF length(trim(coalesce(p_typed_name,''))) < 2 OR tax__norm_name(p_typed_name) !~ '[a-z]' THEN
    RAISE EXCEPTION 'Type your full name to sign';
  END IF;
  p_selected_items := coalesce(p_selected_items, '{}');
  SELECT array_agg(x) INTO v_bad FROM unnest(p_selected_items) x
   WHERE NOT EXISTS (SELECT 1 FROM tax_disclosure_items i WHERE i.document_id = d.id AND i.item_code = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'Not part of this consent: %', array_to_string(v_bad, ', '); END IF;
  IF d.requires_items AND cardinality(p_selected_items) = 0 THEN
    RAISE EXCEPTION 'Nothing was selected, so there is nothing to consent to. Close the screen to decline.';
  END IF;
  IF p_duration_days IS NOT NULL AND p_duration_days NOT BETWEEN 1 AND 3650 THEN RAISE EXCEPTION 'Duration must be 1 to 3650 days'; END IF;
  SELECT acct_default_entity(p.tenant_id) INTO v_entity;
  INSERT INTO tax_consents(tenant_id, entity_id, document_id, presentation_id, content_sha256, rendered_body, signer_user_id, signer_name, signer_title,
                           signature_method, signature_hash, dwell_ms, client_ip, user_agent, expires_on)
  VALUES (p.tenant_id, v_entity, d.id, p.id, p.content_sha256, p.rendered_body, auth.uid(), trim(p_typed_name), p_signer_title,
          'typed_name', tax__sha(p.content_sha256 || '|' || tax__norm_name(p_typed_name) || '|' || now()::text), v_dwell, p_client_ip, p_user_agent,
          CASE WHEN d.default_duration_days IS NULL AND p_duration_days IS NULL THEN NULL
               ELSE current_date + coalesce(p_duration_days, d.default_duration_days) END)
  RETURNING id INTO v_id;
  INSERT INTO tax_consent_items(tenant_id, consent_id, item_id, granted)
  SELECT p.tenant_id, v_id, i.id, i.item_code = ANY (p_selected_items) FROM tax_disclosure_items i WHERE i.document_id = d.id;
  UPDATE tax_screen_presentations SET used_at = now() WHERE id = p.id;
  -- copy to the taxpayer (also always available through tax_consent_copy)
  SELECT email INTO v_email FROM auth.users WHERE id = auth.uid();
  BEGIN
    IF v_email IS NULL THEN RAISE EXCEPTION 'no email on the account'; END IF;
    v_mail := email_enqueue(p.tenant_id, 'tax-consent-' || v_id, app__default_from(p.tenant_id), ARRAY[v_email],
                'Your signed copy: ' || d.title, NULL,
                p.rendered_body || E'\n\nSelected: ' || coalesce(nullif(array_to_string(p_selected_items, ', '), ''), '(none)') ||
                E'\nSigned by ' || trim(p_typed_name) || ' on ' || current_date || '.', 'transactional', 'tax_consents', v_id);
    UPDATE tax_consents SET copy_email_id = v_mail WHERE id = v_id;
  EXCEPTION WHEN OTHERS THEN
    UPDATE tax_consents SET copy_error = SQLERRM WHERE id = v_id;
  END;
  RETURN v_id;
END $$;

-- @seq 585
CREATE FUNCTION public.taxprod_deferred(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'taxprod'
    AS $$
DECLARE x jsonb;o jsonb;g text;ca numeric;tb numeric;r numeric;va numeric;diff numeric;
 dta numeric;dtl numeric;gross_dta numeric:=0;gross_dtl numeric:=0;total_va numeric:=0;
 opening_net numeric;closing_net numeric;movement numeric;expense numeric;total_exp numeric:=0;
 layers jsonb:='[]';groups jsonb:='[]';ids text[];id text;odta numeric;odtl numeric;ova numeric;
BEGIN
 PERFORM taxprod.unique_ids(p->'layers','layers');PERFORM taxprod.unique_ids(p->'opening_groups','opening_groups');
 PERFORM taxprod.arr(p->'unresolved','unresolved');
 FOR x IN SELECT value FROM jsonb_array_elements(p->'layers') LOOP
 g:=taxprod.txt(x->'group','group');PERFORM taxprod.txt(x->'rate_ref','enacted rate evidence');
 PERFORM taxprod.txt(x->'source_ref','source_ref');
 ca:=taxprod.num(x->'carrying','carrying');tb:=taxprod.num(x->'tax_basis','tax_basis');
 IF ca<0 OR tb<0 THEN RAISE EXCEPTION 'Use reviewed signed-difference treatment for negative bases';END IF;
 r:=taxprod.num(x->'rate','rate',false);IF r<0 OR r>1 THEN RAISE EXCEPTION 'Rate must be 0..1';END IF;
 IF jsonb_typeof(x->'reversal_year') IS DISTINCT FROM 'number' OR (x->>'reversal_year')::numeric<>trunc((x->>'reversal_year')::numeric)
 OR (x->>'reversal_year')::int NOT BETWEEN 2000 AND 2200 THEN RAISE EXCEPTION 'Reversal year required';END IF;
 IF x->>'classification'='asset' THEN diff:=ca-tb;
 ELSIF x->>'classification'='liability' THEN diff:=tb-ca;
 ELSE RAISE EXCEPTION 'Asset/liability classification required';END IF;
 dta:=round(greatest(-diff,0)*r,2);dtl:=round(greatest(diff,0)*r,2);
 va:=taxprod.num(x->'valuation_allowance','valuation_allowance');
 IF va<0 OR va>dta THEN RAISE EXCEPTION 'Valuation allowance exceeds DTA';END IF;
 gross_dta:=gross_dta+dta;gross_dtl:=gross_dtl+dtl;total_va:=total_va+va;
 layers:=layers||jsonb_build_array(jsonb_build_object('id',x->>'id','group',g,
 'taxable_temporary_difference',diff,'gross_dta',dta,'dtl',dtl,'valuation_allowance',va,
 'net_liability',dtl-dta+va,'rate',r,'rate_ref',x->>'rate_ref','reversal_year',x->'reversal_year'));
 END LOOP;
 SELECT array_agg(DISTINCT v) INTO ids FROM (
 SELECT value->>'group' v FROM jsonb_array_elements(layers)
 UNION SELECT value->>'id' v FROM jsonb_array_elements(p->'opening_groups')) z;
 FOREACH id IN ARRAY coalesce(ids,ARRAY[]::text[]) LOOP
 SELECT value INTO o FROM jsonb_array_elements(p->'opening_groups') WHERE value->>'id'=id;
 IF o IS NULL THEN RAISE EXCEPTION 'Explicit opening balances required for group % (including zero)',id;END IF;
 odta:=taxprod.num(o->'dta','opening dta');odtl:=taxprod.num(o->'dtl','opening dtl');
 ova:=taxprod.num(o->'valuation_allowance','opening VA');
 IF odta<0 OR odtl<0 OR ova<0 OR ova>odta THEN RAISE EXCEPTION 'Invalid opening deferred balances';END IF;
 movement:=taxprod.num(o->'non_pl_net_liability_movement','non-P&L movement');
 opening_net:=odtl-odta+ova;
 SELECT coalesce(sum((value->>'net_liability')::numeric),0) INTO closing_net
 FROM jsonb_array_elements(layers) WHERE value->>'group'=id;
 expense:=closing_net-opening_net-movement;total_exp:=total_exp+expense;
 groups:=groups||jsonb_build_array(jsonb_build_object('id',id,'opening_net_liability',opening_net,
 'closing_net_liability',closing_net,'non_pl_movement',movement,'deferred_tax_expense',expense,
 'presented_asset',greatest(-closing_net,0),'presented_liability',greatest(closing_net,0)));
 END LOOP;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(p->'unresolved')=0 THEN 'measured_workpaper' ELSE 'blocked' END,
 'gross_dta',gross_dta,'gross_dtl',gross_dtl,'valuation_allowance',total_va,
 'deferred_tax_expense',total_exp,'layers',layers,'netting_groups',groups,
 'blocking_issues',p->'unresolved','filing_ready',false,
 'limitations','Realizability, exceptions, uncertain positions, enacted-rate applicability and group eligibility require review');
END $$;

-- @seq 586
CREATE FUNCTION public.taxprod_nol(p_income numeric, p_pre2018 numeric, p_post2017 numeric, p_post_limit_fraction numeric, p_section382_remaining numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE pre numeric;post numeric;remaining numeric;
BEGIN
 IF p_income IS NULL OR p_pre2018 IS NULL OR p_post2017 IS NULL OR p_post_limit_fraction IS NULL OR p_section382_remaining IS NULL
 OR least(p_income,p_pre2018,p_post2017,p_section382_remaining)<0
 OR p_post_limit_fraction<0 OR p_post_limit_fraction>1 THEN RAISE EXCEPTION 'Invalid reviewed NOL inputs';END IF;
 IF p_income::text IN ('NaN','Infinity') OR p_pre2018::text IN ('NaN','Infinity')
 OR p_post2017::text IN ('NaN','Infinity') OR p_post_limit_fraction::text IN ('NaN','Infinity')
 OR p_section382_remaining::text IN ('NaN','Infinity') THEN RAISE EXCEPTION 'Finite values required';END IF;
 pre:=least(p_income,p_pre2018,p_section382_remaining);
 remaining:=p_income-pre;
 post:=least(p_post2017,round(remaining*p_post_limit_fraction,2),p_section382_remaining-pre);
 RETURN jsonb_build_object('pre2018_used',pre,'post2017_used',post,'total_deduction',pre+post,
 'remaining_taxable_income',remaining-post,'pre2018_remaining',p_pre2018-pre,'post2017_remaining',p_post2017-post,
 'note','Caller must determine eligible unexpired lots, correct taxable-income base, year rules and 382 ordering');
END $$;

-- @seq 587
CREATE FUNCTION public.taxprod_partnership(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'taxprod'
    AS $$
DECLARE per jsonb;it jsonb;x jsonb;sh jsonb;al jsonb;st date;en date;lastdate date;d1 date;d2 date;
 a numeric;total numeric;gp numeric:=0;gp_exp numeric;ratio numeric;lines jsonb:='[]';checks jsonb:='[]';
 summaries jsonb;issues jsonb;method text;cat text;amount numeric;
BEGIN
 PERFORM taxprod.unique_ids(p->'periods','periods');PERFORM taxprod.unique_ids(p->'items','items');
 PERFORM taxprod.arr(p->'unresolved','unresolved');issues:=p->'unresolved';
 PERFORM taxprod.txt(p->'agreement_ref','agreement_ref');
 st:=(taxprod.txt(p->'start','start'))::date;en:=(taxprod.txt(p->'end','end'))::date;
 IF en<st OR en-st>370 OR jsonb_array_length(p->'periods')=0 THEN RAISE EXCEPTION 'Invalid tax period';END IF;
 lastdate:=st-1;
 FOR per IN SELECT value FROM jsonb_array_elements(p->'periods') ORDER BY (value->>'start')::date LOOP
 d1:=taxprod.txt(per->'start','period start')::date;d2:=taxprod.txt(per->'end','period end')::date;
 IF d1<>lastdate+1 OR d2<d1 OR d2>en THEN RAISE EXCEPTION 'Ownership periods have gap, overlap or invalid boundary';END IF;
 lastdate:=d2;PERFORM taxprod.arr(per->'partners','partners');
 SELECT jsonb_agg(jsonb_build_object('partner_id',value->'partner_id','share',value->'profit')) INTO sh FROM jsonb_array_elements(per->'partners');
 PERFORM public.partnership18_split(0,sh);
 SELECT jsonb_agg(jsonb_build_object('partner_id',value->'partner_id','share',value->'loss')) INTO sh FROM jsonb_array_elements(per->'partners');
 PERFORM public.partnership18_split(0,sh);
 END LOOP;
 IF lastdate<>en THEN RAISE EXCEPTION 'Ownership periods do not cover full tax year';END IF;
 FOR it IN SELECT value FROM jsonb_array_elements(p->'items') LOOP
 a:=taxprod.num(it->'amount','item amount');PERFORM taxprod.txt(it->'source_ref','item source_ref');
 cat:=taxprod.txt(it->'category','category');
 IF cat NOT IN ('ordinary_business','rental_real_estate','other_rental','interest','ordinary_dividends','royalties',
 'short_term_capital','long_term_capital','section1231','other_income','section179','charitable',
 'other_deduction','tax_exempt_interest','other_tax_exempt','nondeductible','gp_services','gp_capital','distributions_cash') THEN
 RAISE EXCEPTION 'Category requires supplemental implementation: %',cat;END IF;
 SELECT value INTO per FROM jsonb_array_elements(p->'periods') WHERE value->>'id'=it->>'period_id';
 IF per IS NULL THEN RAISE EXCEPTION 'Unknown item period';END IF;
 -- Mandatory allocation_class prevents absent special-case flags from defaulting to ordinary.
 IF it->>'allocation_class' IS NULL THEN RAISE EXCEPTION 'allocation_class required';END IF;
 IF it->>'allocation_class' NOT IN ('ordinary','reviewed_special','direct') THEN
 issues:=issues||jsonb_build_array('Unsupported allocation class for item '||(it->>'id'));CONTINUE;END IF;
 IF it->>'allocation_class'='direct' THEN
 IF cat NOT IN ('gp_services','gp_capital','distributions_cash') OR a<0 THEN RAISE EXCEPTION 'Invalid direct category/amount';END IF;
 PERFORM taxprod.txt(it->'recipient','recipient');
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(per->'partners') v WHERE v->>'partner_id'=it->>'recipient') THEN RAISE EXCEPTION 'Recipient outside period membership';END IF;
 sh:=jsonb_build_array(jsonb_build_object('partner_id',it->'recipient','share',1));method:='direct';
 IF cat IN ('gp_services','gp_capital') THEN gp:=gp+a;END IF;
 ELSE
 IF cat IN ('gp_services','gp_capital','distributions_cash') THEN RAISE EXCEPTION 'Direct assignment required';END IF;
 IF it->>'allocation_class'='reviewed_special' THEN
 PERFORM taxprod.txt(it->'review_ref','special review_ref');PERFORM taxprod.txt(it->'agreement_ref','special agreement_ref');
 sh:=it->'shares';PERFORM taxprod.arr(sh,'special shares');
 FOR x IN SELECT value FROM jsonb_array_elements(sh) LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(per->'partners') v WHERE v->>'partner_id'=x->>'partner_id') THEN RAISE EXCEPTION 'Special share outside period membership';END IF;
 END LOOP;method:='reviewed_special';
 ELSE
 SELECT jsonb_agg(jsonb_build_object('partner_id',v->'partner_id','share',CASE WHEN a<0 THEN v->'loss' ELSE v->'profit' END))
 INTO sh FROM jsonb_array_elements(per->'partners') v;method:=CASE WHEN a<0 THEN 'period_loss' ELSE 'period_profit' END;
 END IF;
 END IF;
 -- Extraordinary status must be explicit. An extraordinary item requires event-date
 -- ownership review rather than ordinary period weighting.
 IF jsonb_typeof(it->'extraordinary') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Explicit extraordinary boolean required';END IF;
 IF (it->>'extraordinary')::boolean THEN
 IF it->>'allocation_class'<>'reviewed_special' THEN RAISE EXCEPTION 'Extraordinary item requires reviewed special shares';END IF;
 d1:=taxprod.txt(it->'event_date','event date')::date;
 IF d1<(per->>'start')::date OR d1>(per->>'end')::date THEN RAISE EXCEPTION 'Event outside allocation period';END IF;
 END IF;
 al:=public.partnership18_split(a,sh);
 SELECT sum((value->>'amount')::numeric) INTO total FROM jsonb_array_elements(al);
 IF total<>a THEN RAISE EXCEPTION 'Cent reconciliation failure';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(al) LOOP
 lines:=lines||jsonb_build_array(x||jsonb_build_object('item_id',it->>'id','period_id',it->>'period_id',
 'category',cat,'method',method,'source_ref',it->>'source_ref','review_ref',it->>'review_ref'));END LOOP;
 checks:=checks||jsonb_build_array(jsonb_build_object('item_id',it->>'id','input',a,'allocated',total,'difference',a-total));
 END LOOP;
 -- GP reconciliation is not a second deduction. It proves assignment matches upstream
 -- GP obligations. The caller supplies reviewed expense/capital split including unpaid GP.
 gp_exp:=taxprod.num(p->'gp_deducted_upstream','gp deducted upstream');
 amount:=taxprod.num(p->'gp_capitalized_upstream','gp capitalized upstream');
 IF gp_exp<0 OR amount<0 OR gp<>gp_exp+amount THEN
 issues:=issues||jsonb_build_array('Guaranteed payments do not reconcile to upstream deductible plus capitalized amounts');END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('partner_id',pid,'category',category,'amount',amt) ORDER BY pid,category),'[]')
 INTO summaries FROM(SELECT value->>'partner_id' pid,value->>'category' category,sum((value->>'amount')::numeric) amt
 FROM jsonb_array_elements(lines) GROUP BY 1,2) q;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(issues)=0 THEN 'allocated_workpaper' ELSE 'blocked' END,
 'allocation_lines',lines,'partner_category_totals',summaries,'item_reconciliation',checks,
 'guaranteed_payments_assigned',gp,'guaranteed_payments_additional_deduction',0,
 'blocking_issues',issues,'filing_ready',false);
END $$;

-- @seq 588
CREATE FUNCTION public.taxprod_provision(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'taxprod'
    AS $$
DECLARE ti numeric;r numeric;gross numeric;credit numeric;ref numeric;pay numeric;deferred numeric;
 current numeric;total numeric;book numeric;
BEGIN
 ti:=taxprod.num(p->'taxable_income','taxable_income');r:=taxprod.num(p->'rate','rate',false);
 IF r<0 OR r>1 THEN RAISE EXCEPTION 'Rate must be 0..1';END IF;
 PERFORM taxprod.txt(p->'rate_ref','rate_ref');
 credit:=taxprod.num(p->'available_nonrefundable_credits','credits');
 ref:=taxprod.num(p->'refundable_payment_credits','refundable payment credits');
 pay:=taxprod.num(p->'payments','payments');deferred:=taxprod.num(p->'deferred_tax_expense','deferred expense');
 book:=taxprod.num(p->'pretax_book_income','pretax book income');
 IF least(credit,ref,pay)<0 THEN RAISE EXCEPTION 'Negative payment/credit';END IF;
 gross:=round(greatest(ti,0)*r,2);current:=gross-least(gross,credit);total:=current+deferred;
 RETURN jsonb_build_object('gross_current_tax',gross,'credits_used',least(gross,credit),
 'unused_credit',greatest(credit-gross,0),'current_tax_expense',current,
 'deferred_tax_expense',deferred,'total_tax_expense',total,
 'balance_due',greatest(current-pay-ref,0),'overpayment',greatest(pay+ref-current,0),
 'statutory_tax_on_book',round(book*r,2),'rate_reconciliation_unexplained',total-round(book*r,2),
 'effective_rate',CASE WHEN book<>0 THEN total/book ELSE NULL END,
 'filing_ready',false,'note','Credits are prequalified inputs. Refundable credits treated here as payments, not ASC740 expense benefits. No special corporate taxes included.');
END $$;

-- @seq 589
CREATE FUNCTION public.taxprod_reconcile(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'taxprod'
    AS $$
DECLARE x jsonb; book numeric; b numeric;t numeric;d numeric;perm numeric:=0;temp numeric:=0;
 adds numeric:=0;subs numeric:=0;lines jsonb:='[]';issues jsonb;taxable numeric;
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'object' THEN RAISE EXCEPTION 'Object required';END IF;
 book:=taxprod.num(p->'pretax_book_income','pretax_book_income');
 PERFORM taxprod.unique_ids(p->'differences','differences');
 PERFORM taxprod.arr(p->'unresolved','unresolved');issues:=p->'unresolved';
 PERFORM taxprod.txt(p->'source_trial_balance_ref','source_trial_balance_ref');
 FOR x IN SELECT value FROM jsonb_array_elements(p->'differences') LOOP
 PERFORM taxprod.txt(x->'citation','citation');PERFORM taxprod.txt(x->'source_ref','source_ref');
 IF x->>'kind' IS NULL OR x->>'kind' NOT IN ('permanent','temporary') THEN RAISE EXCEPTION 'Difference kind required';END IF;
 b:=taxprod.num(x->'book_income','book_income');t:=taxprod.num(x->'tax_income','tax_income');d:=t-b;
 IF x->>'kind'='permanent' THEN perm:=perm+d;ELSE temp:=temp+d;
 PERFORM taxprod.txt(x->'temporary_ref','temporary_ref');END IF;
 adds:=adds+greatest(d,0);subs:=subs+greatest(-d,0);
 lines:=lines||jsonb_build_array(jsonb_build_object('id',x->>'id','kind',x->>'kind',
 'book',b,'tax',t,'adjustment',d,'source_ref',x->>'source_ref','citation',x->>'citation',
 'temporary_ref',x->>'temporary_ref'));
 END LOOP;
 taxable:=book+perm+temp;
 RETURN jsonb_build_object('status',CASE WHEN jsonb_array_length(issues)=0 THEN 'reconciled_workpaper' ELSE 'blocked' END,
 'pretax_book_income',book,'permanent_adjustments',perm,'temporary_adjustments',temp,
 'tax_income_before_nol_special_deductions',taxable,
 'workpaper_schedule',jsonb_build_object('book_pretax',book,'additions',adds,'subtractions',subs,'tax_income',taxable,
 'reconciliation_difference',book+adds-subs-taxable),
 'difference_schedule',lines,'blocking_issues',issues,'filing_ready',false,
 'schedule_note','Generic signed M-1/M-3 supporting reconciliation, NOT completed form-specific M-1/M-3');
END $$;

-- @seq 590
CREATE FUNCTION public.taxprod_save(p_tenant uuid, p_entity uuid, p_kind text, p_key text, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'taxprod'
    AS $$
DECLARE h text;r taxprod.runs%ROWTYPE;outp jsonb;
BEGIN
 PERFORM public.acct_assert_access(p_tenant);
 IF NOT EXISTS(SELECT 1 FROM public.acct_entities WHERE tenant_id=p_tenant AND id=p_entity) THEN RAISE EXCEPTION 'Tenant/entity mismatch';END IF;
 IF p_key IS NULL OR btrim(p_key)='' OR length(p_key)>200 THEN RAISE EXCEPTION 'Idempotency key required (1..200)';END IF;
 h:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant::text||p_entity::text||p_kind||p_key,0));
 SELECT * INTO r FROM taxprod.runs WHERE tenant_id=p_tenant AND entity_id=p_entity AND kind=p_kind AND idempotency_key=p_key;
 IF FOUND THEN
 IF r.input_sha256 IS DISTINCT FROM h THEN RAISE EXCEPTION 'Idempotency key reused with changed input';END IF;
 RETURN r.result||jsonb_build_object('run_id',r.id);END IF;
 CASE p_kind
 WHEN 'reconcile' THEN outp:=public.taxprod_reconcile(p_input);
 WHEN 'deferred' THEN outp:=public.taxprod_deferred(p_input);
 WHEN 'provision' THEN outp:=public.taxprod_provision(p_input);
 WHEN 'partnership' THEN outp:=public.taxprod_partnership(p_input);
 ELSE RAISE EXCEPTION 'Unsupported calculation kind';END CASE;
 INSERT INTO taxprod.runs(tenant_id,entity_id,kind,idempotency_key,input_sha256,input,result,created_by)
 VALUES(p_tenant,p_entity,p_kind,p_key,h,p_input,outp,auth.uid()) RETURNING * INTO r;
 RETURN outp||jsonb_build_object('run_id',r.id);
END $$;

-- @seq 621
CREATE FUNCTION tax16.assert_worker() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT tax16.is_worker() THEN RAISE EXCEPTION 'Trusted service worker required' USING ERRCODE='42501'; END IF;
END $$;

-- @seq 622
CREATE FUNCTION tax16.can_read(p_tenant uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF tax16.is_worker() THEN RETURN true; END IF;
 IF auth.uid() IS NULL THEN RETURN false; END IF;
 PERFORM public.acct_assert_access(p_tenant);
 RETURN true;
EXCEPTION WHEN insufficient_privilege OR raise_exception THEN RETURN false;
END $$;

-- @seq 623
CREATE FUNCTION tax16.guard_mef_transmission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE s tax16.settings%ROWTYPE; rdy boolean;
BEGIN
 SELECT * INTO s FROM tax16.settings WHERE singleton;
 IF NEW.status IN ('queued','transmitting','submitted') AND
 (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
  IF NEW.delivery_mode<>'efile' OR NOT s.transmission_enabled THEN
   RAISE EXCEPTION 'Transmission disabled; preparation and downloads remain available'; END IF;
  SELECT efile_ready INTO rdy FROM tax16.form_support WHERE form_code=NEW.form_code;
  IF rdy IS DISTINCT FROM true THEN RAISE EXCEPTION 'Form not released for electronic filing'; END IF;
  IF NEW.tax16_package_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM tax16.rule_packages p WHERE p.id=NEW.tax16_package_id
    AND p.tax_year=NEW.tax_year AND p.form_code=NEW.form_code AND p.status='active') THEN
   RAISE EXCEPTION 'Active year/form rule package required'; END IF;
 END IF;
 IF NEW.delivery_mode='download' THEN NEW.fee_amount:=0; END IF;
 IF NEW.delivery_mode='efile' AND NEW.status='queued' AND
 (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN
  NEW.fee_amount:=CASE WHEN s.filing_fee_enabled AND s.fee_effective_at<=now()
    THEN s.filing_fee_amount ELSE 0 END;
 END IF;
 RETURN NEW;
END $$;

-- @seq 624
CREATE FUNCTION tax16.guard_package() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'tax16'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status<>'draft' THEN RAISE EXCEPTION 'Released package cannot be deleted'; END IF;
  RETURN OLD;
 END IF;
 IF NEW.rules_sha256<>encode(sha256(convert_to(NEW.rules::text,'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Package hash mismatch'; END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'draft' AND
 (NEW.rules IS DISTINCT FROM OLD.rules OR NEW.rules_sha256 IS DISTINCT FROM OLD.rules_sha256
 OR NEW.tax_year<>OLD.tax_year OR NEW.form_code<>OLD.form_code
 OR NEW.engine_version<>OLD.engine_version OR NEW.code<>OLD.code OR NEW.version<>OLD.version) THEN
  RAISE EXCEPTION 'Released package content is immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'draft' AND NEW.status='draft' THEN
  RAISE EXCEPTION 'Publish a new version rather than reopening a released package'; END IF;
 IF NEW.status IN ('validated','active') THEN
  IF NOT EXISTS(SELECT 1 FROM tax16.rule_sources WHERE package_id=NEW.id)
  OR NOT EXISTS(SELECT 1 FROM tax16.rule_tests WHERE package_id=NEW.id)
  OR EXISTS(SELECT 1 FROM tax16.rule_tests WHERE package_id=NEW.id AND passed IS DISTINCT FROM true) THEN
   RAISE EXCEPTION 'Source references and passing regression tests required'; END IF;
 END IF;
 RETURN NEW;
END $$;

-- @seq 625
CREATE FUNCTION tax16.guard_tenant_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'tax16'
    AS $$
DECLARE r public.mef_returns%ROWTYPE; e uuid;
BEGIN
 IF TG_TABLE_NAME='entity_profiles' THEN
  SELECT tenant_id INTO e FROM public.acct_entities WHERE id=NEW.entity_id;
  IF e IS DISTINCT FROM NEW.tenant_id THEN RAISE EXCEPTION 'Entity tenant mismatch'; END IF;
 ELSE
  SELECT * INTO r FROM public.mef_returns WHERE id=NEW.return_id;
  IF NOT FOUND OR r.tenant_id<>NEW.tenant_id THEN RAISE EXCEPTION 'Return tenant mismatch'; END IF;
  IF TG_TABLE_NAME IN ('calculation_runs','artifacts') THEN
   IF NEW.return_version<>r.version THEN RAISE EXCEPTION 'Stale return version'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;

