CREATE FUNCTION tax16.is_worker() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(auth.role(),'') = 'service_role';
$$;

-- @seq 628
CREATE FUNCTION taxprod.arr(v jsonb, label text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'array' THEN RAISE EXCEPTION '% must be an array',label;END IF;
 IF jsonb_array_length(v)>10000 THEN RAISE EXCEPTION '% exceeds 10000-entry limit',label;END IF;
END $$;

-- @seq 629
CREATE FUNCTION taxprod.immutable_run() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'Evidence is append-only; create a new run';END $$;

-- @seq 630
CREATE FUNCTION taxprod.num(v jsonb, label text, cents boolean DEFAULT true) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n numeric;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'number' THEN RAISE EXCEPTION '% must be numeric',label;END IF;
 n:=v::text::numeric;
 IF n::text IN ('NaN','Infinity','-Infinity') OR abs(n)>999999999999999999 THEN RAISE EXCEPTION '% out of supported bounds',label;END IF;
 IF cents AND n<>round(n,2) THEN RAISE EXCEPTION '% must have cent precision',label;END IF;
 RETURN n;
END $$;

-- @seq 631
CREATE FUNCTION taxprod.txt(v jsonb, label text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'string' OR btrim(v#>>'{}')='' THEN RAISE EXCEPTION '% must be nonempty text',label;END IF;
 RETURN v#>>'{}';
END $$;

-- @seq 632
CREATE FUNCTION taxprod.unique_ids(v jsonb, label text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE x jsonb;
BEGIN
 PERFORM taxprod.arr(v,label);
 FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM taxprod.txt(x->'id',label||'.id');END LOOP;
 IF (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(v))<>jsonb_array_length(v) THEN RAISE EXCEPTION '% duplicate IDs',label;END IF;
END $$;

